local config = {
  ui_story_5061_50610101_1_dialog_content = "Registro de Investigação, Entrada 154.",
  ui_story_5061_50610101_2_dialog_content = "27 de setembro, 22:00. Nevando.",
  ui_story_5061_50610101_3_dialog_content = "Após viajar até os confins de Northland, estou atualmente me aproximando do local da centenária <color=#FFB400>Aurorastorm</color>.",
  ui_story_5061_50610101_4_dialog_content = "Este foi um raro evento anômalo relacionado à Aurora registrado na história de Northland, e a lenda do Espírito da Aurora perdurou por muito tempo desde então.",
  ui_story_5061_50610101_5_dialog_content = "Os Aurorianos nascem dependendo de Lúmina, e a Aurora só aparece quando Lúmina compacta encontra certas condições em um determinado ambiente.",
  ui_story_5061_50610101_6_dialog_content = "É uma manifestação extrema de energia bruta... talvez a forma mais pura de Lúmina!",
  ui_story_5061_50610101_7_dialog_content = "Ele chama a todos os Aurorianos como um farol na noite, servindo como um símbolo de sua existência.",
  ui_story_5061_50610101_8_dialog_content = "Naturalmente, um fenômeno raro como este é destinado a atrair admiração e curiosidade das pessoas... E eu não sou diferente!",
  ui_story_5061_50610101_9_dialog_content = "Há várias teorias sobre a origem da Aurora. A teoria da Turbulência da Zona Escura, a teoria da Luz Sagrada, a teoria da Fragmentação Polar, a teoria da Tempestade Eletromagnética...",
  ui_story_5061_50610101_10_dialog_content = "Mas, pessoalmente, acredito que a teoria mais plausível seja a da Fonte de Energia Antiga.",
  ui_story_5061_50610101_11_dialog_content = "A Aurora possui uma quantidade inconcebível de poder, provavelmente aproveitada pelas antigas civilizações escondidas logo abaixo de nossos pés.",
  ui_story_5061_50610101_12_dialog_content = "Os textos de Lumópolis indicam que a primeira Aurora surgiu de um conjunto de ruínas antigas. No entanto, as próprias ruínas específicas são amplamente debatidas.",
  ui_story_5061_50610101_13_dialog_content = "Se essa hipótese estiver correta, encontrarei a verdadeira origem da Aurora no final da minha excursão?",
  ui_story_5061_50610101_14_dialog_content = "...",
  ui_story_5061_50610101_15_dialog_content = "São agora 22:14. Acredito que estou além das fronteiras de Northland, assim como fora do alcance protetor do Farol.",
  ui_story_5061_50610101_16_dialog_content = "Vejo várias figuras escuras de pé nas planícies congeladas. Talvez sejam restos de árvores antigas, ou possivelmente...",
  ui_story_5061_50610101_17_dialog_content = "...",
  ui_story_5061_50610101_18_dialog_content = "Para evitar a detecção dos Eclipsites, vou desligar o gravador agora.",
  ui_story_5061_50610101_19_dialog_content = "Se alguém encontrar esta gravação, significa que minha sorte deu uma guinada para o pior. Se isso acontecer, por favor, entregue isso à Corte de Northland.",
  ui_story_5061_50610101_20_dialog_content = "Espero sinceramente que as futuras gerações achem minha pesquisa útil para desvendar as origens da Aurora.",
  ui_story_5061_50610101_21_dialog_content = "Para que um dia, possamos finalmente entender...",
  ui_story_5061_50610101_22_dialog_content = "De onde vieram os Aurorianos e em que tipo de mundo vivemos.",
  ui_story_5061_50610101_23_dialog_content = "... Ah! É aquele—?!",
  ui_story_5061_50610101_24_dialog_content = "No gelo, é... uma pessoa?!",
  ui_story_5061_50610101_25_dialog_content = "... Um viajante perdido? Ou talvez... Será que este é o lendário Espírito da Aurora?",
  ui_story_5061_50610101_26_dialog_content = "... Ela ainda está viva?",
  ui_story_5061_50610201_1_dialog_content = "(Ofegante) Finalmente consegui!",
  ui_story_5061_50610201_2_dialog_content = "A neve está ficando cada vez mais pesada! Eu preciso voltar para dentro do Colosso!",
  ui_story_5061_50610201_3_dialog_content = "Apenas esfregue suas mãos juntas e respire nelas...",
  ui_story_5061_50610201_4_dialog_content = "Haaah—Haaaaah—",
  ui_story_5061_50610201_5_dialog_content = "Não adianta! Mesmo quando eu faço isso, minhas mãos ainda estão congelando!",
  ui_story_5061_50610201_6_dialog_content = "Haha, bem, você ESTÁ em Northland, afinal de contas...",
  ui_story_5061_50610201_7_dialog_content = "Se eu soubesse que ia estar tão frio, teria trazido mais equipamentos de sobrevivência para o inverno para o trabalho!",
  ui_story_5061_50610201_8_dialog_content = "De fato, se Carleen estivesse por perto, ela definitivamente teria te lembrado.",
  ui_story_5061_50610201_9_dialog_content = "Na verdade, ela provavelmente já teria feito para você uma bela xícara de chá quentinho até agora!",
  ui_story_5061_50610201_10_dialog_content = "(Suspiros) Já sinto falta de estar de volta em Lumópolis e Illumina com todos! Pelo menos eu não estaria congelando até a morte.",
  ui_story_5061_50610201_11_dialog_content = "Desculpe por não podermos ir com você desta vez...",
  ui_story_5061_50610201_12_dialog_content = "Mas eu prometo que nos divertiremos muito juntos em Northland na próxima vez!",
  ui_story_5061_50610201_13_dialog_content = "E se a Carleen vier junto, ela até pode nos levar em um passeio de carruagem!",
  ui_story_5061_50610201_14_dialog_content = "(Se houver uma próxima vez, prefiro ficar na minha Colossus...)",
  ui_story_5061_50610201_15_dialog_content = "Tudo bem, de verdade. Estou apenas um pouco entediado aqui e não consigo pensar em mais nada para conversar.",
  ui_story_5061_50610201_16_dialog_content = "Eu sei. É fácil se sentir solitário quando você está viajando pela neve sozinho. Por que não experimenta o novo comunicador que o Oficial Gronru te deu?",
  ui_story_5061_50610201_17_dialog_content = "Ele capta todos os tipos de sons e sinais de todo o mundo. Mesmo se você estiver sozinho no Colossus, tenho certeza de que isso ajudará a melhorar seu humor!",
  ui_story_5061_50610201_18_dialog_content = "Você pode ser capaz de ouvir o som das máquinas de Illumina, ou até mesmo uma transmissão musical de Umbraton! Incrível, né?",
  ui_story_5061_50610201_19_dialog_content = "... Seria muito mais incrível se eu pudesse realmente escolher o que ouvir...",
  ui_story_5061_50610201_20_dialog_content = "Acho que você vai ter que confiar no Oficial Gronru!",
  ui_story_5061_50610201_21_dialog_content = "Certifique-se de cuidar bem de si mesmo lá fora. E se você vir algo interessante, lembre-se de nos contar para que possamos ver juntos algum dia!",
  ui_story_5061_50610201_22_dialog_content = "De qualquer forma, enquanto Queen Bethlehem estiver por perto, Northland deve estar perfeitamente segura. Caso contrário, eu nunca teria ficado tranquilo deixando você sozinho!",
  ui_story_5061_50610201_23_dialog_content = "Bem, o treinamento está prestes a começar, então eu devo ir. Falo com você em breve!",
  ui_story_5061_50610201_24_dialog_content = "Tá bom.",
  ui_story_5061_50610201_25_dialog_content = "...",
  ui_story_5061_50610201_26_dialog_content = "Porque o tempo e o lugar estão errados?",
  ui_story_5061_50610201_26X1_dialog_content = "Northland realmente é... Exatamente como Carleen e os outros descrevem...",
  ui_story_5061_50610201_27_dialog_content = "A Northland de hoje não se parece mais com o encantador conto de fadas que Carleen uma vez me descreveu...",
  ui_story_5061_50610201_27X1_dialog_content = "É completamente diferente de lugares como Lumopolis e as Subcidades.",
  ui_story_5061_50610201_28_dialog_content = "<color=#e8d9bb>Vastos, frios e misteriosos, as florestas se estendem infinitamente enquanto os picos das montanhas se erguem altos, grandiosos e majestosos.</color>",
  ui_story_5061_50610201_29_dialog_content = "<color=#e8d9bb>Há poucos vestígios de civilização nesta terra, como se nada tivesse mudado ao longo de milhares de anos.</color>",
  ui_story_5061_50610201_30_dialog_content = "Está tão quieto aqui...",
  ui_story_5061_50610201_31_dialog_content = "... Talvez eu deva experimentar o comunicador do Gronru. Qualquer coisa para quebrar esse pesado silêncio.",
  ui_story_5061_50610201_32_option_content = "Ativar Comunicador",
  ui_story_5061_50610201_33_dialog_content = "(Clique) Zumbido, zumbido...",
  ui_story_5061_50610201_34_dialog_content = "Zumbido, zumbido...",
  ui_story_5061_50610201_35_dialog_content = "... Não está funcionando de jeito nenhum!",
  ui_story_5061_50610201_36_dialog_content = "Todo esse chiado está me dando dor de cabeça. Acho que vou desligar...",
  ui_story_5061_50610201_37_dialog_content = "... A... Alguém?!",
  ui_story_5061_50610201_38_dialog_content = "... Isso é... o... Pedindo ajuda!",
  ui_story_5061_50610201_39_dialog_content = "Hã? Um pedido de socorro?!",
  ui_story_5061_50610201_40_dialog_content = "Repito: Esta é a crista nordeste do Pico do Cedro, na fronteira de Northland, a uma altitude de 3.200 metros.",
  ui_story_5061_50610201_41_dialog_content = "Encontrei alguém preso no gelo. A situação parece grave e não consigo realizar o resgate.",
  ui_story_5061_50610201_42_dialog_content = "Qualquer pessoa que possa estar ouvindo, por favor, venha equipado com ferramentas para quebrar gelo e equipamentos de aquecimento para o resgate!",
  ui_story_5061_50610201_43_dialog_content = "Pico do Cedro... Isso não é longe daqui!",
  ui_story_5061_50610201_44_dialog_content = "Aguente firme! A ajuda está a caminho!",
  ui_story_5061_50610201_45_dialog_content = "(O clima e o terreno dificultaram o pouso rápido... Eu só espero não estar muito atrasado.)",
  ui_story_5061_50610201_46_dialog_content = "Olá? Tem alguém aí? Eu captei um pedido de socorro dessa localização!",
  ui_story_5061_50610201_47_dialog_content = "Ei! Alguém pode me ouvir?! Acho que vou ter que usar meus poderes... Força Boo—Uau!",
  ui_story_5061_50610201_48_dialog_content = "(A neve tá tão profunda! E só tem mais neve à vista... Será que eles estão enterrados em algum lugar debaixo de tudo isso?!)",
  ui_story_5061_50610201_49_dialog_content = "<color=#e8d9bb>Crocante—</color>",
  ui_story_5061_50610201_50_dialog_content = "O que foi isso?",
  ui_story_5061_50610201_51_dialog_content = "<color=#e8d9bb>Estalando—</color>",
  ui_story_5061_50610201_52_dialog_content = "Hah...",
  ui_story_5061_50610201_53_dialog_content = "Que som é esse... Será que alguém está realmente enterrado na neve?!",
  ui_story_5061_50610201_54_dialog_content = "Aguente firme, vou te tirar daí!!",
  ui_story_5061_50610201_55_dialog_content = "Haah... Haah...",
  ui_story_5061_50610201_56_dialog_content = "Roaaaar—",
  ui_story_5061_50610201_57_dialog_content = "Hã?!?!",
  ui_story_5061_50610201_58_dialog_content = "Ativando técnica de emergência!",
  ui_story_5061_50610201_59_dialog_content = "Gaaah!",
  ui_story_5061_50610201_60_dialog_content = "Fique atrás de mim! Eu vou lidar com isso!",
  ui_story_5061_50610202_1_dialog_content = "Growl...",
  ui_story_5061_50610202_2_dialog_content = "Ufa, estou salvo. Obrigado...",
  ui_story_5061_50610202_3_dialog_content = "Desculpe-me, mas você deve ser...",
  ui_story_5061_50610202_4_dialog_content = "Cores! Eu vi Lumina de todas as cores durante nossa batalha agora há pouco! Elas estavam claras como o dia!",
  ui_story_5061_50610202_5_dialog_content = "Era como se o caminho para a vitória aparecesse em minha mente... Eu sabia exatamente o que tinha que fazer!",
  ui_story_5061_50610202_6_dialog_content = "Eu me movi com o fluxo de Lumina como uma folha ao vento. Tudo parecia tão natural...",
  ui_story_5061_50610202_7_dialog_content = "Mas como? Como pode ser isso?! Preciso saber mais sobre isso! Eu preciso!!!",
  ui_story_5061_50610202_8_dialog_content = "Você deve ser o Celestita sobre o qual tenho ouvido falar ultimamente! Você se importaria de responder algumas das minhas perguntas? Eu adoraria aprender mais sobre suas habilidades e sobre suas experiências pilotando o Colosso!",
  ui_story_5061_50610202_9_dialog_content = "E-Espere um segundo! Eu ficaria feliz em conversar, mas não deveríamos pelo menos nos apresentar? Meu nome é PlayerName.",
  ui_story_5061_50610202_10_dialog_content = "Oh! D-Desculpe por isso, às vezes eu fico um pouco animado... É um mau hábito meu, mas espero que não tenha te incomodado ou algo assim?",
  ui_story_5061_50610202_11_dialog_content = "Meu nome é Antony e sou um estudioso do folclore. Você veio por causa do chamado de socorro que enviei?",
  ui_story_5061_50610202_12_dialog_content = "O clima aqui é tão extremo que fiquei soterrado na neve. Tudo que eu pude fazer foi sentar e esperar até ouvir a ajuda se aproximando...",
  ui_story_5061_50610202_13_dialog_content = "Ainda bem que consegui ouvir você chegar!",
  ui_story_5061_50610202_14_dialog_content = "Isso mesmo. Eu também não sou exatamente feito para esse tipo de ambiente. Não conseguia sentir ninguém aqui, achei que estava resgatando uma pessoa, mas acabou sendo um Eclipsite...",
  ui_story_5061_50610202_15_dialog_content = "Enfim, você mencionou algo sobre uma pessoa presa também, não mencionou?",
  ui_story_5061_50610202_16_dialog_content = "É verdade! Mas a situação é... um pouco difícil de acreditar. É completamente diferente do que eu pensava originalmente...",
  ui_story_5061_50610202_17_dialog_content = "Aqui, venha comigo.",
  ui_story_5061_50610202_18_dialog_content = "Ah, e cuidado com aqueles icicles. Alguns deles têm Eclipsitas presos dentro.",
  ui_story_5061_50610202_19_dialog_content = "Mas existem toneladas deles...",
  ui_story_5061_50610202_20_dialog_content = "Aqui está ela. Vá em frente, dê uma olhada no gelo.",
  ui_story_5061_50610202_21_dialog_content = "É uma garota... dentro do gelo?",
  ui_story_5061_50610202_22_dialog_content = "... Ela ainda está viva?!",
  ui_story_5061_50610202_23_dialog_content = "Eu acredito que sim, sim.",
  ui_story_5061_50610202_24_dialog_content = "Apesar de estar presa no gelo, seu corpo não apresenta sinais visíveis de ter congelado até a morte.",
  ui_story_5061_50610202_25_dialog_content = "Na verdade, parece que ela está apenas dormindo. Como se essa tumba congelada não fosse diferente de uma cama...",
  ui_story_5061_50610202_26_dialog_content = "Talvez eu possa me conectar com ela telepaticamente!",
  ui_story_5061_50610202_27_option_content = "Aumento de Força",
  ui_story_5061_50610202_28_dialog_content = "Nngh... Hã...?",
  ui_story_5061_50610202_29_dialog_content = "Quando foi que eu... dormi...?",
  ui_story_5061_50610202_30_dialog_content = "Como isso aconteceu? Eu tinha... algo importante para fazer...",
  ui_story_5061_50610202_31_dialog_content = "Se eu falhar... Todas as aldeias próximas, não, todo o Northland... Minha irmã!!!",
  ui_story_5061_50610202_32_dialog_content = "Ela realmente está viva! E a mente dela está respondendo de forma muito intensa também!",
  ui_story_5061_50610202_33_dialog_content = "Isso é maravilhoso! Devemos tentar tirá-la do gelo? Ou talvez nossa melhor opção seja derretê-lo primeiro...",
  ui_story_5061_50610202_34_dialog_content = "Espere, estou sentindo algumas flutuações estranhas de energia por perto...",
  ui_story_5061_50610202_35_dialog_content = "E parece que ela é a fonte disso. Ela deve ter uma quantidade enorme de Lumina armazenada em seu corpo...",
  ui_story_5061_50610202_36_dialog_content = "E quando a acordei com meus poderes, ela começou a usar seus Luminatics inconscientemente!",
  ui_story_5061_50610202_37_dialog_content = "<color=#e8d9bb>(Sons de rachaduras)</color>",
  ui_story_5061_50610202_38_dialog_content = "Parece que o gelo está começando a se partir.",
  ui_story_5061_50610202_39_dialog_content = "A Lumina que criou este gelo está fluindo rapidamente. Nesse ritmo, ela pode ser capaz de se libertar. Isso é ótimo!",
  ui_story_5061_50610202_40_dialog_content = "Ótimo, meu pé! E se ela provocar uma avalanche ou algo assim?!",
  ui_story_5061_50610202_41_dialog_content = "Precisamos recuar para uma distância segura antes que acabemos enterrados junto com o resto desses Eclipsitas!",
  ui_story_5061_50610202_42_dialog_content = "Roaaaar—",
  ui_story_5061_50610202_43_dialog_content = "Foi só isso que precisou para libertá-los?!",
  ui_story_5061_50610202_44_dialog_content = "Ah não... Eles estão vindo direto para nós!",
  ui_story_5061_50610202_45_dialog_content = "Eclipsitas realmente são criaturas fascinantes. Se nossas vidas não estivessem em tanto perigo, eu adoraria estudá-los mais de perto...",
  ui_story_5061_50610202_46_dialog_content = "<color=#e8d9bb>(Grunhidos)</color>",
  ui_story_5061_50610202_47_dialog_content = "Graças a Deus, não são muitos. Eu devo conseguir chamar a atenção deles enquanto você escapa.",
  ui_story_5061_50610202_48_dialog_content = "Você vai enfrentar todos eles sozinho?! Eles não estão exatamente interessados na sua pesquisa, sabe!",
  ui_story_5061_50610202_49_dialog_content = "Não se preocupe. Como um semi-humano, sou mais do que capaz de me defender. Além disso, já estive nesse tipo de situação várias vezes.",
  ui_story_5061_50610202_50_dialog_content = "Pelo menos, eu deveria ser capaz de sobreviver aos ataques deles até que se desgastem.",
  ui_story_5061_50610202_51_dialog_content = "Isso é... uma estratégia bem única.",
  ui_story_5061_50610202_52_dialog_content = "Mas já que estou aqui, farei tudo o que puder para ajudá-lo a vencer. Sou um Celestita, não vou decepcioná-lo.",
  ui_story_5061_50610202_53_dialog_content = "Estou com você! Vamos mostrar a esses monstros o que acontece quando seguimos o fluxo da Lúmina!",
  ui_story_5061_50610202_54_dialog_content = "Roaaaar—!",
  ui_story_5061_50610202_55_dialog_content = "Urgh! E-eu ainda não terminei...",
  ui_story_5061_50610202_56_dialog_content = "Concentre-se, Antony! Você precisa seguir o caminho da Lumina aos seus pés—Hã?",
  ui_story_5061_50610202_57_dialog_content = "M-Meus pés... estão congelados?!",
  ui_story_5061_50610202_58_dialog_content = "A temperatura está caindo drasticamente...",
  ui_story_5061_50610202_59_dialog_content = "Quem está... aí?",
  ui_story_5061_50610202_60_dialog_content = "Graagh!",
  ui_story_5061_50610302_1_dialog_content = "Nossa!",
  ui_story_5061_50610302_2_dialog_content = "A nevasca finalmente diminuiu... Você está bem?",
  ui_story_5061_50610302_3_dialog_content = "Estou bem, mas e ela...?",
  ui_story_5061_50610302_4_dialog_content = "...",
  ui_story_5061_50610302_5_dialog_content = "Cuidado!",
  ui_story_5061_50610302_6_dialog_content = "O pulso e a respiração dela estão normais, mas ela está fria como gelo e seu rosto parece um pouco pálido...",
  ui_story_5061_50610302_7_dialog_content = "O que vamos fazer agora?",
  ui_story_5061_50610302_8_dialog_content = "Acordem-na e tentem mantê-la consciente. Vou procurar um caminho até a vila mais próxima.",
  ui_story_5061_50610302_9_dialog_content = "Certo!",
  ui_story_5061_50610302_10_dialog_content = "Desculpe se isso é um pouco brusco... Mas a melhor maneira de te despertar completamente é entrando na sua mente novamente!",
  ui_story_5061_50610302_11_dialog_content = "Acorde!!!",
  ui_story_5061_50610302_12_dialog_content = "Ah?!",
  ui_story_5061_50610302_13_option_content = "Ei, oi... Você está bem?",
  ui_story_5061_50610302_14_dialog_content = "Desculpe por te acordar assim. Você está machucado? Lembra de alguma coisa?",
  ui_story_5061_50610302_15_dialog_content = "Quem é você? E-Eu nunca te vi antes na minha vida...",
  ui_story_5061_50610302_16_option_content = "Hum, que estranho.",
  ui_story_5061_50610302_17_dialog_content = "Você é uma espécie de deusa dos picolés de gelo? Aquele poder que você liberou antes foi insano!",
  ui_story_5061_50610302_18_dialog_content = "C-Como assim, deusa do picolé?",
  ui_story_5061_50610302_19_dialog_content = "Quem é você e do que você está falando?!",
  ui_story_5061_50610302_20_dialog_content = "Bem, meu nome é PlayerName e sou um celestita. Meu amigo e eu encontramos você preso no gelo...",
  ui_story_5061_50610302_21_dialog_content = "... Ou pelo menos você estava presa, mas conseguiu se libertar há apenas alguns minutos atrás.",
  ui_story_5061_50610302_22_dialog_content = "Como você está se sentindo? Alguma coisa dói?",
  ui_story_5061_50610302_23_dialog_content = "Um Celestita...? O que um Celestita estaria fazendo aqui...",
  ui_story_5061_50610302_24_dialog_content = "O gelo... Eu me lembro de lutar contra uma horda de Eclipsitas, mas depois...",
  ui_story_5061_50610302_25_dialog_content = "Espere... Estou morto? Será que este lugar é o além...?",
  ui_story_5061_50610302_26_dialog_content = "... Errado em todos os aspectos. Estamos em uma montanha perto da fronteira de Northland, e ainda estamos muito vivos.",
  ui_story_5061_50610302_27_dialog_content = "Uma montanha perto da fronteira de Northland... Isso mesmo! Eu vim aqui procurando minha irmã!",
  ui_story_5061_50610302_28_dialog_content = "<color=#FFB400>Maninha</color>... Me diga, eles conseguiram resgatar os outros <color=#FFB400>patrulheiros</color> também?",
  ui_story_5061_50610302_29_dialog_content = "Você quer dizer que ainda há outras pessoas presas no gelo?",
  ui_story_5061_50610302_30_dialog_content = "Não, quero dizer o...",
  ui_story_5061_50610302_31_dialog_content = "Espere, você quer dizer que não sabe?! Foi aqui que aconteceu a <color=#FFB400>Aurorastorm</color>! O Tribunal enviou dezenas de patrulheiros para investigar!",
  ui_story_5061_50610302_32_dialog_content = "Exceto... Nenhum deles voltou. Tem certeza de que não viu mais ninguém?",
  ui_story_5061_50610302_33_dialog_content = "(Eu não sabia nada sobre isso quando vim para Northland... Antony também não mencionou nada.)",
  ui_story_5061_50610302_34_dialog_content = "Meu nome é Zarya. Minha irmã, Alina, é a capitã dos patrulheiros. Me diga, você realmente não viu mais ninguém por aqui?",
  ui_story_5061_50610302_35_dialog_content = "Desculpe mesmo, mas eu não vi... Espera, o que é isso?!",
  ui_story_5061_50610302_36_dialog_content = "Roaaaar—",
  ui_story_5061_50610302_37_dialog_content = "(Merda! Fiquei tão envolvido conversando com ela. Eu esqueci completamente de prestar atenção ao nosso redor!)",
  ui_story_5061_50610302_38_dialog_content = "... Floresça, Geluz!",
  ui_story_5061_50610302_39_dialog_content = "Eca—",
  ui_story_5061_50610302_40_dialog_content = "(Tão poderosa... Mesmo não estando em sua força total, ela derrotou quatro Eclipsitas com um único ataque!)",
  ui_story_5061_50610302_41_dialog_content = "Há Eclipsitas aqui... Isso significa que minha irmã está em ainda maior perigo!",
  ui_story_5061_50610302_42_dialog_content = "Eu.. Eu tenho que encontrá-la imediatamente! Alina!",
  ui_story_5061_50610302_43_dialog_content = "Aguente firme! Você acordou há pouco tempo! É muito perigoso lutar em sua condição atual!",
  ui_story_5061_50610302_44_dialog_content = "Mas minha irmã também pode estar em perigo!",
  ui_story_5061_50610302_45_dialog_content = "Não entendo como ou porquê, mas finalmente tenho uma maneira de lutar contra os Eclipsitas agora!",
  ui_story_5061_50610302_46_dialog_content = "Se não posso salvar minha família com esse poder, então qual é o meu valor—",
  ui_story_5061_50610302_47_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5061_50610302_48_dialog_content = "Ei! Controle-se! Não haverá esperança alguma para você se desmaiar em um lugar como este!",
  ui_story_5061_50610302_49_dialog_content = "Se-Se algo acontecer comigo, então por favor... Ajude-me a encontrar minha irmã e diga a ela, diga que eu não quero ser deixada novamente.",
  ui_story_5061_50610302_50_dialog_content = "...",
  ui_story_5061_50610302_51_dialog_content = "Ei—!",
  ui_story_5061_50610302_52_dialog_content = "Respiro da Primavera—",
  ui_story_5061_50610302_53_dialog_content = "São esses... botões de flor? E por que de repente me sinto tão confortável...?",
  ui_story_5061_50610302_54_dialog_content = "Desculpe-me, mas você é PlayerName?",
  ui_story_5061_50610302_55_dialog_content = "Sim, sou eu.",
  ui_story_5061_50610302_56_dialog_content = "E-er, o-olá... Meu nome é Leah e eu sou um patrulheiro de Northland... Q-quer dizer, um patrulheiro em treinamento.",
  ui_story_5061_50610302_57_dialog_content = "O Sr. Antony pediu-me para levar todos em segurança.",
  ui_story_5061_50610302_58_dialog_content = "F-Fique tranquilo, eu conheço muito bem os caminhos e esconderijos das montanhas nesta área. Eu juro guiar todos de volta à área de proteção de Queen Bethlehem com segurança.",
  ui_story_5061_50610302_59_dialog_content = "Hum, acho que é tudo. Esqueci de algo?",
  ui_story_5061_50610401_1_dialog_content = "Aqui, pegue algumas frutas recém-colhidas...",
  ui_story_5061_50610401_2_dialog_content = "É excelente para se proteger do frio.",
  ui_story_5061_50610401_3_dialog_content = "Eu pretendia trazer mais remédios e suprimentos, mas nossos estoques já estão extremamente limitados. Me desculpe...",
  ui_story_5061_50610401_4_dialog_content = "Por favor, não peça desculpas por isso, já estamos gratos pela sua ajuda. Você não quer um pouco, Antony?",
  ui_story_5061_50610401_5_dialog_content = "Oh! Desculpe, eu não estava prestando atenção agora... Obrigado.",
  ui_story_5061_50610401_6_dialog_content = "Então, como está o Zarya?",
  ui_story_5061_50610401_7_dialog_content = "Assim como você disse antes, a condição dela está longe de ser normal. Eu também detecto uma enorme quantidade de Lumina em seu corpo.",
  ui_story_5061_50610401_8_dialog_content = "Para ser sincero, um Auroriano comum não seria capaz de suportar tanto Lumina.",
  ui_story_5061_50610401_9_dialog_content = "No entanto, ela não apenas conseguiu sobreviver ao ser envolvida em gelo, como também conseguiu se libertar sozinha. Isso não é nada comum.",
  ui_story_5061_50610401_10_dialog_content = "De fato. Fiquei igualmente chocado ao descobrir que ela ainda estava viva quando investiguei sua mente.",
  ui_story_5061_50610401_11_dialog_content = "No entanto, comunicar com ela não tem sido fácil. Ela continua falando sobre patrulheiros e sua irmã, e algo sobre a \"Aurora Tempestade\"...",
  ui_story_5061_50610401_12_dialog_content = "Ela não ouviu uma palavra do que eu disse.",
  ui_story_5061_50610401_13_dialog_content = "Os patrulheiros estão bem e ninguém está desaparecido ultimamente, certo, Leah?",
  ui_story_5061_50610401_14_dialog_content = "Ah! E-Estava falando comigo...?",
  ui_story_5061_50610401_15_dialog_content = "Sim, você está certo. Todos os patrulheiros retornaram de seus postos, sãos e salvos.",
  ui_story_5061_50610401_16_dialog_content = "Isso está de acordo com o meu entendimento também. Afinal, estamos em Northland; enquanto permanecermos dentro de suas fronteiras, estaremos perfeitamente seguros.",
  ui_story_5061_50610401_17_dialog_content = "Todos sabem disso. Em caso de emergência, todos nós sabemos que devemos nos refugiar no território do Queen para garantir nossa segurança.",
  ui_story_5061_50610401_18_dialog_content = "Eu tenho uma pergunta.",
  ui_story_5061_50610401_19_dialog_content = "O Farol de Northland... Será que ele realmente pode proteger todo o Northland com apenas o poder de Queen Bethlehem?",
  ui_story_5061_50610401_19X1_dialog_content = "Desde a minha primeira visita a Northland, notei que todos falam sobre a proteção concedida pelo Queen e pelo Farol.",
  ui_story_5061_50610401_20_dialog_content = "Após minha última visita ao Palácio Invernal, não consigo parar de me preocupar com o bem-estar dela.",
  ui_story_5061_50610401_20X1_dialog_content = "Eu sei que Queen Bethlehem é um dos mais nobres e poderosos Aurorianos de todo o Astra.",
  ui_story_5061_50610401_21_dialog_content = "Ela me disse que a pior parte já ficou no passado e que eu não deveria me preocupar mais... Mas será que ela está realmente bem?",
  ui_story_5061_50610401_21X1_dialog_content = "E o que exatamente torna o Farol tão especial? Ele realmente é capaz de cobrir uma nação inteira com uma barreira protetora?",
  ui_story_5061_50610401_22_dialog_content = "Sua Majestade é... a pessoa mais confiável e segura que eu conheço! Se ela diz algo, então deve ser verdade!",
  ui_story_5061_50610401_22X1_dialog_content = "E sim, é realmente especial! Enquanto o Farol permanecer aceso, nenhum Eclipsita pode entrar em Northland.",
  ui_story_5061_50610401_23_dialog_content = "Tenho certeza de que há mais no Farol do que isso. Afinal, como nossa única defesa contra os Eclipsitas por mais de um milênio, deve conter todos os tipos de segredos dentro de suas paredes.",
  ui_story_5061_50610401_23X1_dialog_content = "Em resumo, o Farol é a estrutura de defesa única de Northland, assim como Lumopolis e Illumina têm as suas.",
  ui_story_5061_50610401_24_dialog_content = "Como moradores de Northland, acreditar de todo coração em nossa rainha é o primeiro passo para ajudá-la.",
  ui_story_5061_50610401_24X1_dialog_content = "O Farol é nossa maior arma, bem como nossa maior defesa.",
  ui_story_5061_50610401_25_dialog_content = "No entanto, estou muito mais interessado na Aurorastorm...",
  ui_story_5061_50610401_26_dialog_content = "Tem certeza que a Srta. Zarya disse isso?",
  ui_story_5061_50610401_27_dialog_content = "Sim, e eu também me lembro claramente disso. Ela estava determinada a encontrar sua irmã e os outros patrulheiros, e foi por isso que ela veio para cá em primeiro lugar.",
  ui_story_5061_50610401_28_dialog_content = "Mas, além do que aconteceu com ela, nada mais nesta área parece fora do comum.",
  ui_story_5061_50610401_29_dialog_content = "Entendi. Isso me preocupa porque recentemente tenho procurado pistas relacionadas à Aurora Tempestade.",
  ui_story_5061_50610401_30_dialog_content = "Na verdade, é exatamente o motivo pelo qual vim ao Pico do Cedro.",
  ui_story_5061_50610401_31_dialog_content = "Acredito que meu próximo passo seja fazer um levantamento abrangente da área. Só então poderei chegar a uma conclusão mais específica.",
  ui_story_5061_50610401_32_dialog_content = "Com sorte, conseguirei descobrir mais sobre a situação da senhorita Zarya!",
  ui_story_5061_50610401_33_dialog_content = "Estamos contando com você, Antony. Eu também gostaria de saber mais sobre a estranha Lumina que senti nela mais cedo.",
  ui_story_5061_50610401_34_dialog_content = "Essa energia era mais pura do que qualquer coisa que já experimentei...",
  ui_story_5061_50610401_35_dialog_content = "Entendido. Por favor, continue cuidando bem dela enquanto eu reúno mais informações.",
  ui_story_5061_50610401_36_dialog_content = "Hum, devo tentar encontrar um médico?",
  ui_story_5061_50610401_37_dialog_content = "Eu não acho que isso seja necessário. Ela não está doente ou ferida, pelo que eu posso dizer. Meus primeiros socorros devem ser suficientes por enquanto.",
  ui_story_5061_50610401_38_dialog_content = "Você realmente sabe das coisas, Antony. Não apenas é um lutador forte, mas também sabe como prestar tratamento médico!",
  ui_story_5061_50610401_39_dialog_content = "Também estou curioso para saber mais sobre sua pesquisa sobre a origem dos aurorianos.",
  ui_story_5061_50610401_40_dialog_content = "Você estudou em Lumópolis ou Illumina, por acaso?",
  ui_story_5061_50610401_41_dialog_content = "Hmm? De jeito nenhum, por que você pergunta?",
  ui_story_5061_50610401_42_dialog_content = "Ah, é que uma boa amiga minha estudou no exterior no passado e ela realmente aprendeu muito naquela época. Eu estava apenas curioso para saber se você teve uma experiência semelhante.",
  ui_story_5061_50610401_43_dialog_content = "Ah, entendi. Não, minha única educação formal veio das aulas de alfabetização oferecidas às crianças nas áreas de fronteira.",
  ui_story_5061_50610401_44_dialog_content = "Uh, aulas de alfabetização?",
  ui_story_5061_50610401_45_dialog_content = "Isso mesmo! Graças a eles, eu pude ler e entender livros e anotar minhas descobertas.",
  ui_story_5061_50610401_46_dialog_content = "Desculpe se de alguma forma te decepcionei, não sou um estudioso renomado de uma academia prestigiosa.",
  ui_story_5061_50610401_47_dialog_content = "Você está brincando comigo? Se for verdade, isso é ainda mais incrível!",
  ui_story_5061_50610401_48_dialog_content = "Nunca recebi uma educação formal em Astra também. Todo o meu conhecimento foi passado para mim pela minha família...",
  ui_story_5061_50610401_49_dialog_content = "Mas você é um estudante muito melhor do que eu jamais serei!",
  ui_story_5061_50610401_50_dialog_content = "Não há nada de errado com isso! Não importa como ou onde você adquire conhecimento, desde que sua verdadeira sede por aprender e explorar persista!",
  ui_story_5061_50610401_51_dialog_content = "Tô saindo agora!",
  ui_story_5061_50610401_52_dialog_content = "Tudo bem, cuidado lá fora.",
  ui_story_5061_50610401_53_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5061_50610401_54_dialog_content = "(Antony fechou a porta tão suavemente... Provavelmente para evitar acordar Zarya.)",
  ui_story_5061_50610401_55_dialog_content = "(... Depois de tanto lutar e brigar na neve, o calor deste quarto está me deixando com mais sono.)",
  ui_story_5061_50610401_56_dialog_content = "(Parece que Zarya não vai acordar tão cedo. Acho que também devo tentar descansar um pouco.)",
  ui_story_5061_50610402_1_dialog_content = "(Hã? Para onde foram esses Eclipsitas? Está tão quente aqui, e minha boca está tão seca...)",
  ui_story_5061_50610402_2_dialog_content = "<color=#e8d9bb>Estalando—</color>",
  ui_story_5061_50610402_3_dialog_content = "(Ah... Foi só um sonho.)",
  ui_story_5061_50610402_4_dialog_content = "Está tudo bem? Senhorita Zarya?",
  ui_story_5061_50610402_5_dialog_content = "E-Eu não sabia como usar essa chaleira... Eu não percebi que ainda estava quente.",
  ui_story_5061_50610402_6_dialog_content = "Hum, você é a paciente, Srta. Zarya. Acho que você deveria deitar-se novamente, por favor...",
  ui_story_5061_50610402_7_dialog_content = "Estou me sentindo bem agora, eu prometo! Além disso, eu estava apenas tentando servir um copo de água para essa pessoa...",
  ui_story_5061_50610402_8_dialog_content = "Emm... Zarya, você está acordado? O que vocês dois estão fazendo?",
  ui_story_5061_50610402_9_dialog_content = "E quem colocou esse casaco em mim?",
  ui_story_5061_50610402_10_dialog_content = "Isso foi obra da Senhorita Zarya. Quando ela acordou, encontrou você dormindo ao lado da cama dela...",
  ui_story_5061_50610402_11_dialog_content = "Ela se sentiu tão em dívida com você por causa da sua gentileza que me pediu para trazer este casaco para você!",
  ui_story_5061_50610402_12_dialog_content = "E-Eu não faço ideia do que você está falando. Quer dizer, sim, ele realmente me ajudou muito na montanha mais cedo...",
  ui_story_5061_50610402_13_dialog_content = "Mas eu também o salvei de um grupo de Eclipsitas sanguinários. Isso certamente nos torna iguais, certo...?",
  ui_story_5061_50610402_14_dialog_content = "A-Além disso, como um estrangeiro, ele merece receber a verdadeira hospitalidade de Northland, não acha?!",
  ui_story_5061_50610402_15_dialog_content = "...",
  ui_story_5061_50610402_16_dialog_content = "T-Talvez seja porque ainda estou em treinamento, mas eu não entendi muito bem o que você disse agora, Srta. Zarya...",
  ui_story_5061_50610402_17_dialog_content = "Ah! Não, isso não tem nada a ver! É só que...",
  ui_story_5061_50610402_18_dialog_content = "Obrigado.",
  ui_story_5061_50610402_19_dialog_content = "Eu agradeço, mas você realmente deveria tentar ficar na cama e descansar. Você ainda se lembra do que aconteceu na montanha?",
  ui_story_5061_50610402_20_dialog_content = "Eu ia. Estava prestes a procurar minha irmã, mas então você me parou... Por que fez isso?!",
  ui_story_5061_50610402_21_dialog_content = "Se eu não fizesse isso, você acabaria congelado novamente ou no estômago de um Eclipsita. Alguma dessas opções parece boa para você?",
  ui_story_5061_50610402_22_dialog_content = "Você não queria ouvir de jeito nenhum, mas acabei tendo que te carregar de volta todo o caminho.",
  ui_story_5061_50610402_23_dialog_content = "V-Você o quê? Você me carregou montanha abaixo...?",
  ui_story_5061_50610402_24_dialog_content = "E-Eu entendo... Mas eu nunca te pedi para fazer isso, sabe! Eu ficaria bem se você tivesse me deixado lá fora!",
  ui_story_5061_50610402_25_dialog_content = "Dá um tempo, tá bom? Você tá parecendo uma criança agora!",
  ui_story_5061_50610402_26_dialog_content = "... Mas mesmo assim, sei que devo retribuir adequadamente por salvar minha vida. Isso não é algo que uma criança diria, não é?",
  ui_story_5061_50610402_27_dialog_content = "Tudo bem, tudo bem... Mas se alguém merece seus agradecimentos, são o Sr. Antony e Leah. Eles são os que te encontraram e trouxeram remédio.",
  ui_story_5061_50610402_28_dialog_content = "Sim eu sei.",
  ui_story_5061_50610402_29_dialog_content = "Você está se sentindo melhor agora? Se estiver disposto a responder algumas perguntas, talvez possamos encontrar uma maneira de achar sua irmã.",
  ui_story_5061_50610402_30_dialog_content = "Claro.",
  ui_story_5061_50610402_31_dialog_content = "Primeiro de tudo, o que você estava fazendo preso no gelo lá em cima?",
  ui_story_5061_50610402_32_dialog_content = "... Eu prefiro não falar sobre isso.",
  ui_story_5061_50610402_33_dialog_content = "Ei! Você acabou de concordar em conversar e resolver as coisas, e agora está voltando atrás na sua palavra?!",
  ui_story_5061_50610402_34_dialog_content = "V-Você está certo, desculpe.",
  ui_story_5061_50610402_35_dialog_content = "Como mencionei antes, toda a equipe enviada pelo Tribunal para investigar a Aurorastorm nunca mais foi vista ou ouvida.",
  ui_story_5061_50610402_36_dialog_content = "Minha irmã também estava entre eles.",
  ui_story_5061_50610402_37_dialog_content = "Fui até o último local conhecido delas e procurei por horas. Eventualmente, consegui ouvir a voz da minha irmã por perto, apenas para encontrá-las sob ataque de uma horda de Eclipsitas.",
  ui_story_5061_50610402_38_dialog_content = "Havia tantos deles e eu estava preocupado que não chegaria à minha irmã a tempo.",
  ui_story_5061_50610402_39_dialog_content = "Então, enquanto a batalha continuava, eu me escondi sob um monte de cadáveres de Eclipsitas e orei com todo o meu coração...",
  ui_story_5061_50610402_40_dialog_content = "Eu orei para encontrar a força necessária para resgatar minha irmã...",
  ui_story_5061_50610402_41_dialog_content = "De repente, como se minhas preces fossem atendidas, um enorme poder surgiu dentro de mim. Infelizmente, perdi completamente o controle dele e meu Lumina se descontrolou pelo campo de batalha.",
  ui_story_5061_50610402_42_dialog_content = "Os Eclipsitas foram praticamente exterminados, mas, ao mesmo tempo, acabei preso em uma tumba congelada criada pelos meus próprios Lumináticos.",
  ui_story_5061_50610402_43_dialog_content = "Lá eu permaneci adormecido... Até que você me acordou hoje.",
  ui_story_5061_50610402_44_dialog_content = "Então você se prendeu no gelo, né? Sua história fica cada vez mais maluca, viu.",
  ui_story_5061_50610402_45_dialog_content = "E-Eu não queria que isso acontecesse... Eu nunca fui muito bom em controlar meu poder.",
  ui_story_5061_50610402_46_dialog_content = "Então vá em frente e ria! Contanto que você me ajude a encontrar minha irmã depois, você pode rir o quanto quiser...",
  ui_story_5061_50610402_47_dialog_content = "Ainda estou tendo dificuldade em distinguir minhas memórias da realidade...",
  ui_story_5061_50610402_48_dialog_content = "Entendi.",
  ui_story_5061_50610402_49_dialog_content = "Leah, você se importaria de contar para Zarya sobre o que você me disse mais cedo?",
  ui_story_5061_50610402_50_dialog_content = "S-Claro!",
  ui_story_5061_50610402_51_dialog_content = "Quando chegamos aqui, PlayerName me perguntou... Se houve algum incidente de emergência relatado nesta área.",
  ui_story_5061_50610402_52_dialog_content = "Eu disse a ele que esta área tem sido pacífica há algum tempo, já que os Eclipsitas só existem fora das fronteiras de Northland. Além disso, todas as equipes de patrulha relataram ao palácio sem incidentes.",
  ui_story_5061_50610402_53_dialog_content = "A coisa mais próxima que ouvi sobre patrulheiros desaparecidos é quando um de nós viaja um pouco mais longe do que o normal. Quando isso acontece, simplesmente perdemos contato por algum tempo. Batalhas quase nunca acontecem e mortes são ainda menos comuns...",
  ui_story_5061_50610402_54_dialog_content = "E além de rumores de pessoas ouvindo o \"Espírito da Aurora\" nas profundezas das montanhas, não houve nenhuma atividade incomum relatada nesta área.",
  ui_story_5061_50610402_55_dialog_content = "Em outras palavras, apesar de nossos melhores esforços para coletar informações, não aprendemos nada relacionado à sua irmã ou aos patrulheiros desaparecidos.",
  ui_story_5061_50610402_56_dialog_content = "Isso significa que, se o que você está nos contando é verdade, sua irmã deve estar em casa sã e salva.",
  ui_story_5061_50610402_57_dialog_content = "Sério? Eu ficaria tão aliviado se isso fosse verdade...",
  ui_story_5061_50610402_58_dialog_content = "É possível que a resposta esteja em algum lugar da sua mente, Zarya.",
  ui_story_5061_50610402_59_dialog_content = "Hã? C-Como assim?",
  ui_story_5061_50610402_60_dialog_content = "Após combinar as observações de Antony e minhas próprias descobertas...",
  ui_story_5061_50610402_61_dialog_content = "Minha suposição é que você passou muito tempo preso em um ambiente cheio de um tipo estranho de Lumina. Como resultado, suas memórias ficaram um pouco embaralhadas.",
  ui_story_5061_50610402_62_dialog_content = "É por isso que você continua confundindo eventos passados com nossa realidade atual.",
  ui_story_5061_50610402_63_dialog_content = "M-Minhas memórias estão \"embaralhadas\"?",
  ui_story_5061_50610402_64_dialog_content = "De certa forma, sim. Acho que uma maneira melhor de explicar é que algum tipo de energia afetou seu cérebro, dificultando a compreensão do que está acontecendo ao seu redor.",
  ui_story_5061_50610402_65_dialog_content = "Então, em outras palavras, eu fiquei mais burro?!",
  ui_story_5061_50610402_66_dialog_content = "Acho que você está certo... Afinal, em vez de resgatar minha irmã, acabei me prendendo no gelo...",
  ui_story_5061_50610402_67_dialog_content = "Sou totalmente inútil... Acho que não existe um idiota maior no mundo do que eu.",
  ui_story_5061_50610402_68_dialog_content = "Vamos lá Zarya, não diga isso! Olhe só para seus Luminatics de antes! Eu não acho que alguém inútil poderia fazer algo assim!",
  ui_story_5061_50610402_69_dialog_content = "Num piscar de olhos, você me salvou de um destino terrível E eliminou todos os Eclipsites ao nosso redor!",
  ui_story_5061_50610402_70_dialog_content = "A Lumina do seu ataque estava linda. Parecia exatamente com o seu cabelo...",
  ui_story_5061_50610402_71_dialog_content = "Quando Leah te viu pela primeira vez, ela sinceramente pensou que você fosse o Espírito da Aurora!",
  ui_story_5061_50610402_72_dialog_content = "É verdade! O jeito que seu cabelo brilha e resplandece... É como se a Aurora o tivesse abençoado!",
  ui_story_5061_50610402_73_dialog_content = "... Brilhos? Que brilhos?",
  ui_story_5061_50610402_74_dialog_content = "Ah, uh... É um pouco constrangedor admitir, mas eu estava tão fascinado pelo cabelo da Srta. Zarya, já que o meu é tão curto...",
  ui_story_5061_50610402_75_dialog_content = "Então eu ajudei a escovar enquanto ela estava dormindo. Foi quando eu descobri...",
  ui_story_5061_50610402_76_dialog_content = "O cabelo dela emite um brilho suave, como um artefato mágico do passado antigo! Sabe, como nas histórias!",
  ui_story_5061_50610402_77_dialog_content = "M-Meu cabelo?! Mas... Mas isso não é... Meu cabelo nem sempre foi dessa cor!",
  ui_story_5061_50610402_78_dialog_content = "Ela está certa, seu cabelo está emitindo Lumina. Isso deve ser um efeito colateral de ficar presa dentro da sua Luminática por tanto tempo!",
  ui_story_5061_50610402_79_dialog_content = "Você é como uma fonte ambulante de Lumina, liberando-a constantemente no espaço ao seu redor!",
  ui_story_5061_50610402_80_dialog_content = "Isso deve ser o que o Antony estava falando antes... Talvez devêssemos ir perguntar mais sobre isso?",
  ui_story_5061_50610402_81_dialog_content = "Você tem algum meio de contatá-lo, Leah?",
  ui_story_5061_50610402_82_dialog_content = "Sim, na verdade! Vem comigo, e eu te levarei à vila onde ele geralmente realiza suas pesquisas.",
  ui_story_5061_50610402_83_dialog_content = "Se eu tivesse que adivinhar, ele provavelmente está lá agora.",
  ui_story_5061_50610501_1_dialog_content = "Olha só quem está aqui! Leah, nosso Elfo da Primavera!",
  ui_story_5061_50610501_2_dialog_content = "Patrulhando na estrada da montanha novamente hoje?",
  ui_story_5061_50610501_3_dialog_content = "Th-Isso mesmo... Mas hoje não estou na minha rota de patrulha habitual.",
  ui_story_5061_50610501_4_dialog_content = "Tenho... alguns assuntos pessoais para tratar.",
  ui_story_5061_50610501_5_dialog_content = "Esses dois são seus amigos, Leah?",
  ui_story_5061_50610501_6_dialog_content = "Bem, isso é inesperado. Forasteiros aparecendo nesta área remota. E você, jovem, não parece realmente ser de Northland.",
  ui_story_5061_50610501_7_dialog_content = "Huh? Você quer dizer eu?",
  ui_story_5061_50610501_8_dialog_content = "Com certeza. O tempo passou rápido e agora temos turistas por aqui. Antigamente, essa era a linha de frente contra a invasão dos Eclipsitas...",
  ui_story_5061_50610501_9_dialog_content = "A estrada da montanha estava toda coberta de neve e bloqueada. Nós, moradores locais, só podíamos ficar bem atrás das patrulhas...",
  ui_story_5061_50610501_10_dialog_content = "Perdão, mas a qual equipe de patrulha você está se referindo?",
  ui_story_5061_50610501_11_dialog_content = "Eu não acho que ele está falando sobre sua irmã, Srta. Zarya. Se for o caso... Ele está se referindo aos meus pais.",
  ui_story_5061_50610501_12_dialog_content = "Hã? Seus pais também eram patrulheiros de Northland, Leah?",
  ui_story_5061_50610501_13_dialog_content = "Sim, mas... Eles faleceram há muito tempo.",
  ui_story_5061_50610501_14_dialog_content = "Ah, me desculpe. Eu não quis tocar em um assunto tão sensível.",
  ui_story_5061_50610501_15_dialog_content = "Vocês não sabem que Leah é um órfão das patrulhas?",
  ui_story_5061_50610501_16_dialog_content = "A verdade é que, mesmo que os Eclipsitas não estejam se aglomerando aqui como faziam anos atrás, esse trabalho ainda é bastante arriscado.",
  ui_story_5061_50610501_17_dialog_content = "Este não é um lugar como o Palácio Invernal ou o Lago Espelho, vigiado por Sua Majestade a Queen e Senhora Nikinis...",
  ui_story_5061_50610501_18_dialog_content = "Só temos os membros das patrulhas para contar. Mas pensar que crianças como Leah têm que lidar com tudo isso é meio difícil de assistir.",
  ui_story_5061_50610501_19_dialog_content = "Não é... Não é nenhum problema mesmo! Sua Majestade me confiou o Cajado da Primavera e eu tenho tantos amigos me ajudando...",
  ui_story_5061_50610501_20_dialog_content = "Lidar com alguns Eclipsitas não é problema algum... Eu também recebo férias remuneradas, o que é ainda melhor...",
  ui_story_5061_50610501_21_dialog_content = "Suspiro. De qualquer forma, essas coisas ainda precisam de alguém para lidar. E eu não estou exatamente em uma posição para te dar mais conforto.",
  ui_story_5061_50610501_22_dialog_content = "Tudo o que podemos fazer é agradecer por sua dedicação.",
  ui_story_5061_50610501_23_dialog_content = "Um trabalho que precisa ser feito...",
  ui_story_5061_50610501_24_dialog_content = "Sabe, eu percebi que às vezes você parece um pouco solitário.",
  ui_story_5061_50610501_25_dialog_content = "Você não escolheu esse trabalho apenas para ser um patrulheiro, não é? Se for o caso, provavelmente você queria se sentir mais próximo de seus pais seguindo os passos deles...",
  ui_story_5061_50610501_26_dialog_content = "Não é?",
  ui_story_5061_50610501_27_dialog_content = "Ah... Você viu através de mim...",
  ui_story_5061_50610501_28_dialog_content = "É porque às vezes eu me sinto exatamente assim também.",
  ui_story_5061_50610501_29_dialog_content = "Sério? Você também se sente assim?",
  ui_story_5061_50610501_30_dialog_content = "Para ser sincero, eu não sabia realmente o que estava pensando quando aceitei o Cajado da Primavera e me tornei um patrulheiro...",
  ui_story_5061_50610501_31_dialog_content = "Talvez fosse para me aproximar dos meus pais... Ou talvez eu estivesse tão impressionado com Sua Majestade que queria lutar ao lado dela...",
  ui_story_5061_50610501_32_dialog_content = "Mas ao pegar o Cajado da Primavera... Eu fiz essa escolha totalmente por conta própria!",
  ui_story_5061_50610501_33_dialog_content = "E eu queria dar um significado a essa escolha! É por isso... É por isso que decidi continuar sendo um patrulheiro!",
  ui_story_5061_50610501_34_dialog_content = "É uma realização incrível, Leah.",
  ui_story_5061_50610501_35_dialog_content = "A decisão de perseverar no caminho escolhido...",
  ui_story_5061_50610501_36_dialog_content = "Ei, pequeno Leah! Você pode me ajudar a descobrir para onde aqueles dois garotos da casa ao lado correram?",
  ui_story_5061_50610501_37_dialog_content = "Apenas prometi aos pais deles que ficaria de olho neles por um tempo, mas puf, eles sumiram num piscar de olhos!",
  ui_story_5061_50610501_38_dialog_content = "Ah, claro! Na verdade... acho que sei exatamente onde procurá-los!",
  ui_story_5061_50610501_39_dialog_content = "Mas antes disso, posso perguntar... Você já viu o Sr. Antony?",
  ui_story_5061_50610501_40_dialog_content = "De quem você tá falando? Ele é da nossa vila?",
  ui_story_5061_50610501_41_dialog_content = "Er, não exatamente. O Sr. Antony é um estudioso muito bondoso que se mudou para cá recentemente. Ele frequentemente lê para as crianças e ensina a elas sobre estrelas e como usá-las para navegar.",
  ui_story_5061_50610501_42_dialog_content = "Ah, sim. Você refrescou minha memória - alguém assim morando perto da vila.",
  ui_story_5061_50610501_43_dialog_content = "As crianças dizem que ele está sempre mexendo em algum dispositivo estranho, mas é bastante simpático.",
  ui_story_5061_50610501_44_dialog_content = "Então, ele é um estudioso, você diz? Não consigo imaginar isso. Os estudiosos não deveriam ficar trancados dentro de casa lendo livros o dia todo?",
  ui_story_5061_50610501_45_dialog_content = "Mas esse cara, ele está sempre usando esse corpo musculoso dele, correndo pelas montanhas e voltando todo espancado e machucado.",
  ui_story_5061_50610501_46_dialog_content = "Então, o que exatamente ele estuda?",
  ui_story_5061_50610501_47_dialog_content = "Ele está, uh, pesquisando as origens dos aurorianos, como de onde viemos e para onde vamos. Sabe, esse tipo de coisa.",
  ui_story_5061_50610501_48_dialog_content = "Bem, isso é bem estranho. Correr loucamente nas montanhas todos os dias, isso realmente ajuda ele a descobrir todas essas coisas?",
  ui_story_5061_50610501_49_dialog_content = "Por que ele não estuda o que está causando o murchamento das plantações aqui? Não havia muitas alternativas que pudessem crescer neste lugar frio para começar.",
  ui_story_5061_50610501_50_dialog_content = "Não posso realmente dizer a ele o que fazer, desculpe. Além disso, nem tudo tem sua resposta.",
  ui_story_5061_50610501_51_dialog_content = "Mas ainda assim, o Sr. Antony pode ter pesquisado algo relacionado a isso...",
  ui_story_5061_50610501_52_dialog_content = "Ele uma vez me disse... Que \"primavera\" significa duas coisas diferentes para as plantações e para os Aurorianos.",
  ui_story_5061_50610501_53_dialog_content = "Duas primaveras diferentes? O que isso poderia significar?",
  ui_story_5061_50610501_54_dialog_content = "Acho que teremos que perguntar a ele sobre isso quando o encontrarmos.",
  ui_story_5061_50610501_55_dialog_content = "De qualquer forma, eu preciso ir vê-lo.",
  ui_story_5061_50610501_56_dialog_content = "Aqui também. Essas duas crianças adoram fazer muitas perguntas ao Sr. Antony, assim como eu...",
  ui_story_5061_50610501_57_dialog_content = "Provavelmente estão aprendendo algo novo na casa dele se não estão na vila agora.",
  ui_story_5061_50610502_1_dialog_content = "Ufa... Finalmente chegamos.",
  ui_story_5061_50610502_2_dialog_content = "Você disse que a casa dele fica no caminho para o Pico do Cedro, mas ele praticamente mora no pé da montanha.",
  ui_story_5061_50610502_3_dialog_content = "Bem, ele veio aqui para investigar a montanha...",
  ui_story_5061_50610502_4_dialog_content = "Há tantos livros aqui... E olha, um rádio.",
  ui_story_5061_50610502_5_dialog_content = "Ele possui mais livros do que uma biblioteca... Espere, o que é um \"rádio\"?",
  ui_story_5061_50610502_6_dialog_content = "É pronunciado \"rádio\", senhorita Zarya. Pelo que eu entendo, a maioria dos estrangeiros compra-os em Umbraton...",
  ui_story_5061_50610502_7_dialog_content = "São estas... as anotações do Sr. Antony?",
  ui_story_5061_50610502_8_dialog_content = "Deixe-me ver se há alguma pista nele...",
  ui_story_5061_50610502_9_dialog_content = "Vou olhar em volta também... Nossa, ele realmente investigou o problema do crescimento ruim das plantações locais!",
  ui_story_5061_50610502_10_dialog_content = "\"Ano após ano, os campos ao redor da Vila do Cedro não conseguem produzir colheitas saudáveis, e a situação parece piorar a cada ano que passa. Suspeito que o Lumina anormal na área seja o responsável.\"",
  ui_story_5061_50610502_11_dialog_content = "... A caligrafia do Sr. Antony é fofa, não acha? Parece exatamente com a caligrafia de uma criança!",
  ui_story_5061_50610502_12_dialog_content = "(Bem, isso faz sentido, considerando que sua única educação formal foi quando ele era criança...)",
  ui_story_5061_50610502_13_dialog_content = "Ele também tem alguns esquemas desenhados à mão aqui. Um \"bastão de trekking multifuncional\"? Uau, eu não fazia ideia de que o Sr. Antony projetou e construiu aquele bastão de caminhada que ele sempre carrega consigo!",
  ui_story_5061_50610502_14_dialog_content = "Parece que ele passou por algumas versões também. De acordo com suas anotações, ele continuava quebrando durante as lutas com Eclipsitas...",
  ui_story_5061_50610502_15_dialog_content = "Então, ele se concentrou em fortalecer o design nas próximas versões... Isso dificilmente soa como \"multifuncional\" para mim!",
  ui_story_5061_50610502_16_dialog_content = "Estou bem ciente disso. Como um semi-humano, sou mais do que capaz de me defender sozinho. Além disso, já estive nesse tipo de situação inúmeras vezes antes!",
  ui_story_5061_50610502_17_dialog_content = "Pelo menos, eu deveria ser capaz de sobreviver aos ataques deles até que se desgastem.",
  ui_story_5061_50610502_18_dialog_content = "Embora, quando se trata dele... Resistência provavelmente é a função mais útil que algo poderia ter.",
  ui_story_5061_50610502_19_dialog_content = "PlayerName? Ele também menciona algo chamado \"função transmissora\". O que isso significa?",
  ui_story_5061_50610502_20_dialog_content = "<size=45>Cuidado! Eclipsitas!</size>",
  ui_story_5061_50610502_21_dialog_content = "Eclipsitas?! Onde?!?",
  ui_story_5061_50610502_22_dialog_content = "Haha, peguei você! Você é tão medroso!",
  ui_story_5061_50610502_23_dialog_content = "Aí estão vocês dois! Sua família está preocupada demais! Vocês não podem pelo menos avisar aonde vão antes de sumir da vila?",
  ui_story_5061_50610502_24_dialog_content = "Ela está certa, sabe! Também não é legal fazer pegadinhas assim!",
  ui_story_5061_50610502_25_dialog_content = "Crianças que choram Eclipsitas para chamar atenção geralmente são as primeiras a serem comidas!",
  ui_story_5061_50610502_26_dialog_content = "Caramba, por que você tá falando igual minha avó? Ninguém assusta crianças assim hoje em dia!",
  ui_story_5061_50610502_27_dialog_content = "Além disso, conhecemos essa área como a palma de nossas mãos. Sabemos perfeitamente onde é arriscado e onde é seguro.",
  ui_story_5061_50610502_28_dialog_content = "Se você não acredita em nós, podemos mostrar nosso movimento especial — <color=#FFB400>Pesca Eclipsite</color>!",
  ui_story_5061_50610502_29_dialog_content = "Quer ver? Atraímos os Eclipsitas para nos perseguir e os levamos até o brilho do farol. E pum! Os Eclipsitas viram torrada!",
  ui_story_5061_50610502_30_dialog_content = "E alguns Eclipsitas finalmente percebem o que está acontecendo e saem correndo como galinhas - nem dá para descrever o quão engraçado é, hahaha!",
  ui_story_5061_50610502_31_dialog_content = "Vocês estão malucos, crianças?! Isso é muito perigoso!",
  ui_story_5061_50610502_32_dialog_content = "Essas crianças realmente não entendem o quão abençoadas são por viver em paz...",
  ui_story_5061_50610502_33_dialog_content = "Porque é tão chato aqui, sabe. Não tem muita coisa emocionante na fronteira.",
  ui_story_5061_50610502_34_dialog_content = "Exceto pelo que o Sr. Antony disse. Isso é bastante fascinante.",
  ui_story_5061_50610502_35_dialog_content = "O que ele disse?",
  ui_story_5061_50610502_36_dialog_content = "O Sr. Antony disse que as coisas dos contos de fadas eram reais!",
  ui_story_5061_50610502_37_dialog_content = "Você se lembra daquele antigo conto de fadas? Aquele que fala sobre Northland já ter sido um lugar exuberante, verde e cheio de vida?",
  ui_story_5061_50610502_38_dialog_content = "Tenho a sensação de que isso não é apenas um conto de fadas, mas uma história verdadeira do passado!",
  ui_story_5061_50610502_39_dialog_content = "Sério?",
  ui_story_5061_50610502_40_dialog_content = "Encontrei algo que pode provar isso também! Os anéis de uma árvore antiga encontrada congelada no gelo por incontáveis séculos...",
  ui_story_5061_50610502_41_dialog_content = "As mudanças no clima de uma área podem ser vistas nos anéis das árvores, sabia!",
  ui_story_5061_50610502_42_dialog_content = "As seções mais espaçadas dos anéis das árvores indicam um ambiente de crescimento relativamente mais quente naquela época, enquanto as partes mais densas indicam o exato oposto. Quanto à árvore que encontrei, os anéis mais internos são excepcionalmente espaçados.",
  ui_story_5061_50610502_43_dialog_content = "Isso significa que, em algum momento, Northland era um lugar quente! Talvez até tenha vivenciado uma verdadeira estação da primavera!",
  ui_story_5061_50610502_44_dialog_content = "Isso significa que os contos de fadas são reais, não apenas algo inventado para enganar crianças! Vou contar isso para a vovó!",
  ui_story_5061_50610502_45_dialog_content = "Mas, novamente, por que está tão frio em Northland agora?",
  ui_story_5061_50610502_46_dialog_content = "Bem, Northland está localizada em uma altitude muito alta. Além disso, fica bem próxima à Terra da Noite Eterna, que com certeza também é um lugar extremamente frio.",
  ui_story_5061_50610502_47_dialog_content = "De fato, se Northland realmente costumava ser um lugar quente... Então isso significa que o Círculo do Crepúsculo que todos conhecemos não estava aqui...",
  ui_story_5061_50610502_48_dialog_content = "Como era exatamente o mundo todos esses anos atrás...?",
  ui_story_5061_50610502_49_dialog_content = "Sr. Antony, Sr. Antony?",
  ui_story_5061_50610502_50_dialog_content = "Sua voz ficou baixa e o que você estava dizendo estava muito obscuro. Não conseguimos entender.",
  ui_story_5061_50610502_51_dialog_content = "Desculpe por isso, crianças. O mundo está tão cheio de mistérios não resolvidos que até eu tenho dificuldade em entender as coisas.",
  ui_story_5061_50610502_52_dialog_content = "É por isso que é melhor não incomodar outras pessoas com esse tipo de coisa, tá bom?",
  ui_story_5061_50610502_53_dialog_content = "Adoro mistérios não resolvidos! Você sabe o que há por trás da superfície do Lago Espelho, do brilho do Farol e do gelo eterno do Queen?",
  ui_story_5061_50610502_54_dialog_content = "Hahaha! Embora seja um pouco indelicado perguntar sobre os segredos de Sua Majestade, com bastante estudo e comunicação...",
  ui_story_5061_50610502_55_dialog_content = "É possível que saibamos algum dia.",
  ui_story_5061_50610502_56_dialog_content = "Quero estudar com você! Também estou curioso para saber se o Espírito da Aurora é real!",
  ui_story_5061_50610502_57_dialog_content = "Você é mais que bem-vindo para se juntar a mim algum dia, mas esteja avisado: essa linha de trabalho é cheia de perigo e dificuldade. Você precisará treinar tanto sua mente quanto seu corpo se quiser acompanhar.",
  ui_story_5061_50610502_58_dialog_content = "Bem, pequeninos? Vocês acham que essas brincadeiras de vocês contam como treinamento?",
  ui_story_5061_50610502_59_dialog_content = "Tenho certeza de que o Sr. Antony te ensinou melhor, não é?",
  ui_story_5061_50610502_60_dialog_content = "Sinto muito...",
  ui_story_5061_50610502_61_dialog_content = "... Sr. Antony disse que não devemos mexer com os Eclipsitas e que devemos valorizar o poder do Farol, pois Queen tem se esforçado muito para mantê-lo.",
  ui_story_5061_50610502_62_dialog_content = "... Então, não jogamos o jogo de pescar Eclipsites desde então. Estávamos apenas nos exibindo para você agora há pouco...",
  ui_story_5061_50610502_63_dialog_content = "Fico feliz que você entenda. Você faz todo mundo se preocupar com você mesmo quando está apenas se exibindo, sabia?",
  ui_story_5061_50610502_64_dialog_content = "Hmm... me desculpe.",
  ui_story_5061_50610502_65_dialog_content = "Senhorita Zarya... Isso foi incrível! Eu-Eu acho que não sou muito bom em ter conversas difíceis com os outros...",
  ui_story_5061_50610502_66_dialog_content = "Sinceramente, eu estava fingindo ser outra pessoa até agora. Estou tão surpreso que deu tão certo...",
  ui_story_5061_50610502_67_dialog_content = "P-Para dizer a verdade, eu gostaria de aprender a ser mais compassiva como Leah...",
  ui_story_5061_50610502_68_dialog_content = "Sabe, você era bem sensível quando estava dormindo.",
  ui_story_5061_50610502_69_dialog_content = "Não me lembro de ter te pedido—",
  ui_story_5061_50610502_70_dialog_content = "O que o Sr. Antony tem feito ultimamente? Já faz um tempo desde a última vez que ele nos contou histórias...",
  ui_story_5061_50610502_71_dialog_content = "Isso meio que me preocupa...",
  ui_story_5061_50610502_72_dialog_content = "Ele deve estar investigando o que está escrito nestas notas: a Tempestade Auroriana, o estranho Lumina e a caverna congelada no Pico do Cedro!",
  ui_story_5061_50610502_73_dialog_content = "Diz aqui que um grande conjunto de ruínas não identificadas pode existir em algum lugar dentro do Pico do Cedro...",
  ui_story_5061_50610502_74_dialog_content = "... Será que essa é a fonte da estranha Lumina que eu senti antes?",
  ui_story_5061_50610502_75_dialog_content = "(Então, como o Zarya está conectado a tudo isso?)",
  ui_story_5061_50610502_76_dialog_content = "A Aurorastorm... e o Pico do Cedro...",
  ui_story_5061_50610502_77_dialog_content = "O que eu estava fazendo antes de ser congelado? Urgh—",
  ui_story_5061_50610502_78_dialog_content = "(Não quero ficar no escuro para sempre! Eu quero saber... Eu quero lembrar o que aconteceu comigo!)",
  ui_story_5061_50610601_1_dialog_content = "Eu não pensei que nossa busca nos levaria de volta ao lugar onde encontramos você, Zarya.",
  ui_story_5061_50610601_2_dialog_content = "Você está se sentindo bem?",
  ui_story_5061_50610601_3_dialog_content = "Estou bem! Além disso, eu não ia deixar você voltar para a montanha sozinho!",
  ui_story_5061_50610601_4_dialog_content = "Você realmente não deveria se esforçar tanto. Eu poderia ter apenas esperado o Leah voltar e me acompanhar até aqui.",
  ui_story_5061_50610601_5_dialog_content = "Como eu disse! Estou bem, então não se preocupe com isso!",
  ui_story_5061_50610601_6_dialog_content = "Todos estão trabalhando tão duro para me ajudar agora... Que tipo de pessoa eu seria se te deixasse enfrentar o frio e os Eclipsitas sozinho...",
  ui_story_5061_50610601_7_dialog_content = "Estou simplesmente procurando respostas. Nesse aspecto, não sou diferente de Leah ou Antony...",
  ui_story_5061_50610601_8_dialog_content = "Quero enfrentar meu passado e assumir a responsabilidade pelo que fiz, não importa o quão tolo eu possa ter sido. Eu me recuso a fingir que nada aconteceu.",
  ui_story_5061_50610601_9_dialog_content = "Bem, é sempre bom ter um objetivo em mente.",
  ui_story_5061_50610601_10_dialog_content = "Mas... Você não acha que deveria estar se preparando para ir para casa agora? Ou talvez procurando algo para mudar a cor do seu cabelo?",
  ui_story_5061_50610601_11_dialog_content = "... Eu já escrevi uma carta para casa dizendo que estou seguro. No entanto, o mensageiro precisa de um pouco mais de tempo para chegar aqui.",
  ui_story_5061_50610601_12_dialog_content = "(Eu só espero que o endereço que eu lembro ainda esteja certo...)",
  ui_story_5061_50610601_13_dialog_content = "É por isso... Preciso de algo para fazer enquanto isso.",
  ui_story_5061_50610601_14_dialog_content = "Mesmo que minha irmã esteja segura, não posso voltar para casa até entender por que perdi o controle dos meus poderes daquela maneira.",
  ui_story_5061_50610601_15_dialog_content = "Eu só... Eu realmente preciso voltar e descobrir o que aconteceu comigo!",
  ui_story_5061_50610601_16_dialog_content = "Que lindo...",
  ui_story_5061_50610601_17_dialog_content = "Huh...? Do que você está falando?!",
  ui_story_5061_50610601_18_dialog_content = "Estou falando do céu! Acho que eu realmente não percebi isso quando estávamos resgatando você mais cedo.",
  ui_story_5061_50610601_19_dialog_content = "Ouvi alguém dizer que a borda do Círculo Crepúsculo não estava muito longe daqui no nosso caminho de volta descendo a montanha.",
  ui_story_5061_50610601_20_dialog_content = "A-Ah, então era isso que você queria dizer... Isso é bem comum para nós que crescemos nas fronteiras.",
  ui_story_5061_50610601_21_dialog_content = "Antes de hoje, eu só tinha lido sobre isso nos bancos de dados do Soroz. Não é à toa que Antony estava tão interessado em ensinar isso às crianças.",
  ui_story_5061_50610601_22_dialog_content = "Não são muitas pessoas que dedicam tanto tempo ou esforço para entender isso. Eu acredito que o Sr. Antony é a pessoa mais apaixonada que já conheci neste aspecto.",
  ui_story_5061_50610601_23_dialog_content = "Da mesma forma, poucas pessoas buscam entender a fonte do poder do Farol ou os motivos do Queen para proteger Northland.",
  ui_story_5061_50610601_24_dialog_content = "Viver uma vida simples deve ser bem agradável. As opiniões de todos aqui são tão puras e descomplicadas.",
  ui_story_5061_50610601_25_dialog_content = "Talvez isso tenha a ver com o quão desligado Northland está das lutas do resto do mundo. Tem sido exatamente assim por incontáveis anos.",
  ui_story_5061_50610601_26_dialog_content = "Na verdade, Northland é bem diferente do que eu consigo me lembrar. A diferença mais óbvia é como facilmente um estrangeiro como você pode aparecer neste lugar.",
  ui_story_5061_50610601_27_dialog_content = "Suponho que Northland e os Celestitas tenham algo em comum, né? Ambos nos isolamos do mundo para manter nossa neutralidade.",
  ui_story_5061_50610601_28_dialog_content = "Os celestitas têm muito pouco contato com o mundo exterior?",
  ui_story_5061_50610601_29_dialog_content = "Sim. Para evitar conflitos com o resto do mundo e viver em paz, meu povo escolheu se isolar em Eraveil, um lugar onde raramente os estrangeiros pisam.",
  ui_story_5061_50610601_30_dialog_content = "Mesmo desde pequenos, somos ensinados a nunca sair ou interagir com o mundo exterior sem a permissão dos nossos mais velhos.",
  ui_story_5061_50610601_31_dialog_content = "Então, o que fez você sair de Eraveil?",
  ui_story_5061_50610601_32_dialog_content = "Infelizmente, todos os nossos esforços para nos mantermos afastados do resto do mundo não nos mantiveram a salvo dos Eclipsitas.",
  ui_story_5061_50610601_33_dialog_content = "Muitos anos atrás, uma legião de Eclipsitas desceu sobre Eraveil, exterminando todos do meu povo. Eu fui o único sobrevivente.",
  ui_story_5061_50610601_34_dialog_content = "O quê?! Então assim, os lendários Celestitas... Eles todos se foram agora?",
  ui_story_5061_50610601_35_dialog_content = "... Me desculpe. Eu não quis trazer à tona memórias tão dolorosas. Você deve estar se sentindo solitário.",
  ui_story_5061_50610601_36_dialog_content = "Haha, não há nada para se desculpar! Por pior que seja, eu já aceitei o passado.",
  ui_story_5061_50610601_37_dialog_content = "Sinto que consigo entender como você se sente. Embora minhas experiências de vida não sejam nada comparadas às suas.",
  ui_story_5061_50610601_38_dialog_content = "Quando eu era pequeno, causei tantos problemas à minha família porque não conseguia controlar meus Luminatics.",
  ui_story_5061_50610601_39_dialog_content = "Meu pai tinha uma vergonha especial de mim. Ele sempre foi tão distante e me mantinha trancado em casa com medo de que eu prejudicasse seus negócios.",
  ui_story_5061_50610601_40_dialog_content = "Eventualmente, perdi quase todas as minhas habilidades sociais. Eu não tinha amigos nem mesmo a coragem de fazer amigos.",
  ui_story_5061_50610601_41_dialog_content = "Quando penso nisso, minha vida realmente não era diferente de quando eu estava preso no gelo.",
  ui_story_5061_50610601_42_dialog_content = "Você deve ter sofrido a mesma solidão... Preso sozinho, sem ninguém para fazer companhia.",
  ui_story_5061_50610601_43_dialog_content = "No começo, sim. Passei quase toda a minha infância preso em um pequeno espaço. Se eu quisesse aprender algo sobre o mundo exterior, tinha que contar com os bancos de dados do Soroz.",
  ui_story_5061_50610601_44_dialog_content = "Com o tempo, comecei a me perguntar se eu realmente existia no mundo.",
  ui_story_5061_50610601_45_dialog_content = "E agora, mesmo que eu possa ver o mundo com meus próprios olhos... Esse mesmo sentimento ainda me encontra de vez em quando.",
  ui_story_5061_50610601_46_dialog_content = "É por isso que eu escolho continuar em movimento, não importa o quê. Se eu não continuar me movendo, nada jamais mudará.",
  ui_story_5061_50610601_47_dialog_content = "Meu povo já viveu neste mundo e até lutou para protegê-lo. Vou fazer o mesmo.",
  ui_story_5061_50610601_48_dialog_content = "... Sabe, conversar com você é como conversar com minha irmã. Vocês duas são tão fortes e ao mesmo tempo tão bondosas.",
  ui_story_5061_50610601_49_dialog_content = "Ao contrário de mim, que sempre deixo os outros chateados com minhas péssimas decisões...",
  ui_story_5061_50610601_50_dialog_content = "Se eu fosse mais como você, talvez o Pai não tivesse virado as costas para mim. Talvez eu teria resgatado minha irmã...",
  ui_story_5061_50610601_51_dialog_content = "Em vez de acabar preso no gelo.",
  ui_story_5061_50610601_52_dialog_content = "Acabei de lembrar, os Celestitas deveriam ter poderes psíquicos lendários, certo? Você também usou esses poderes para me despertar?",
  ui_story_5061_50610601_53_dialog_content = "Isso mesmo. Na verdade, estou pensando em usá-los novamente agora mesmo.",
  ui_story_5061_50610601_54_dialog_content = "Sabe, você parece estar meio por fora em relação à história recente do Astra.",
  ui_story_5061_50610601_55_dialog_content = "Na verdade, parece que você ficou preso no gelo por muito tempo.",
  ui_story_5061_50610601_56_dialog_content = "E-Ei! Você é quem está me apresentando a todos os tipos de novas informações! Claro que você vai se sentir assim!",
  ui_story_5061_50610601_57_dialog_content = "Shhh! Estou sentindo Eclipsitas!",
  ui_story_5061_50610601_58_dialog_content = "Parece que estamos bem fora da barreira invisível de Queen Bethlehem.",
  ui_story_5061_50610602_1_dialog_content = "Vou manchar a neve com seu sangue, seus monstros!",
  ui_story_5061_50610602_2_dialog_content = "Growl...",
  ui_story_5061_50610602_3_dialog_content = "Isso mal foi um desafio!",
  ui_story_5061_50610602_4_dialog_content = "Isso é estranho... Tem algo errado com esses Eclipsitas.",
  ui_story_5061_50610602_5_dialog_content = "Como assim?",
  ui_story_5061_50610602_6_dialog_content = "Eles estão tentando se afastar de você. Será que eles conseguem sentir seus níveis anormalmente altos de Lumina?",
  ui_story_5061_50610602_7_dialog_content = "Hmph, isso funciona bem para mim. Se essa Lumina estranha é tão assustadora, é melhor eu mantê-la dentro de mim.",
  ui_story_5061_50610602_8_dialog_content = "Além de deixar meu cabelo da mesma cor da Aurora, não parece estar me afetando de nenhuma outra maneira...",
  ui_story_5061_50610602_9_dialog_content = "Vou fazer o meu melhor para controlar isso para não congelar suas pernas novamente!",
  ui_story_5061_50610602_10_dialog_content = "Então você ainda se lembra de mim reclamando daquilo, né?",
  ui_story_5061_50610602_11_dialog_content = "Contanto que você evite minha cabeça, devemos ficar bem. Eu não quero acabar congelado E com cabelos de cores diferentes.",
  ui_story_5061_50610602_12_dialog_content = "Você não precisa parecer tão assustado, sabe!",
  ui_story_5061_50610602_13_dialog_content = "Estou um pouco nervoso ao ver você se familiarizando tanto com seus ataques. Eles só vão ficar mais fortes daqui pra frente...",
  ui_story_5061_50610602_14_dialog_content = "Você realmente acha que eu poderia perder o controle dessa maneira?!",
  ui_story_5061_50610602_15_dialog_content = "Não é completamente impossível, né? Afinal, você acabou congelando a si mesmo junto com metade do Pico do Cedro!",
  ui_story_5061_50610602_16_dialog_content = "Você disse que queria enfrentar seu passado, não importa o quão ruim ele seja, certo? Ou você está tentando jogar a culpa de volta no Espírito da Aurora?",
  ui_story_5061_50610602_17_dialog_content = "Eu...",
  ui_story_5061_50610602_18_dialog_content = "Gaah—Graaah...",
  ui_story_5061_50610602_19_dialog_content = "Tudo bem, admito que posso ter ficado um pouco animado demais quando senti aquele poder dentro de mim...",
  ui_story_5061_50610602_20_dialog_content = "Bom. Que bom que sentimos o mesmo.",
  ui_story_5061_50610602_21_dialog_content = "Falando em empolgação, o Sr. Antony é realmente dedicado à sua pesquisa, não é? Você acha que a Aurora também está conectada a uma fonte de energia antiga?",
  ui_story_5061_50610602_22_dialog_content = "Minha irmã e eu presenciamos a Aurora Tempestade pessoalmente... Será que ela poderia ter se originado nas ruínas próximas também?",
  ui_story_5061_50610602_23_dialog_content = "Provavelmente não saberemos até perguntarmos ao próprio Antony...",
  ui_story_5061_50610602_24_dialog_content = "Mas se eu tivesse que adivinhar, essa estranha Lumina provavelmente é a razão pela qual você tem o poder de congelar montanhas inteiras.",
  ui_story_5061_50610602_25_dialog_content = "E pelo que eu posso sentir, essa Lumina estranha veio de algum lugar subterrâneo. Pode estar conectada à mesma fonte de Lumina que produziu a Aurorastorm.",
  ui_story_5061_50610602_26_dialog_content = "Antony diz que parte do problema é a falta de registros recentes sobre a Aurorastorm... O que significa que não sabemos há quanto tempo isso aconteceu.",
  ui_story_5061_50610602_27_dialog_content = "Mas independentemente de quando aconteceu, não há mais nenhum vestígio disso...",
  ui_story_5061_50610602_28_dialog_content = "Também não há vestígios dos patrulheiros ou da batalha que eles travaram naquela época...",
  ui_story_5061_50610602_29_dialog_content = "Não acredito que minha memória ficou tão pouco confiável...",
  ui_story_5061_50610602_30_dialog_content = "(Hã? Parece que a neve sob nossos pés está brilhando...)",
  ui_story_5061_50610602_31_dialog_content = "Hmm? É um coelho ao lado daquela árvore ali?",
  ui_story_5061_50610602_32_dialog_content = "Coelhos são animais extremamente cautelosos. Se ele está solto, esta área deve estar livre de qualquer perigo oculto...",
  ui_story_5061_50610602_33_dialog_content = "Espere, Zarya! Algo não parece certo neste lugar. Deixe-me tentar usar meus poderes primeiro.",
  ui_story_5061_50610602_34_dialog_content = "De novo? Tudo bem... Se o pior acontecer, eu vou enfrentar o que quer que você consiga encontrar.",
  ui_story_5061_50610602_35_option_content = "Aumento de Força",
  ui_story_5061_50610602_36_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610602_37_dialog_content = "Argh!",
  ui_story_5061_50610602_38_dialog_content = "O que foi isso?! Parece que algo acabou de esfaquear minha cabeça...",
  ui_story_5061_50610602_39_dialog_content = "D-Não me assuste assim! Você está bem...?",
  ui_story_5061_50610602_40_dialog_content = "Eu... acho que posso ter despertado algo...",
  ui_story_5061_50610602_41_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5061_50610602_42_dialog_content = "O que está acontecendo? O que foi aquele barulho?!",
  ui_story_5061_50610602_43_dialog_content = "O chão está desabando!",
  ui_story_5061_50610602_44_dialog_content = "Cuidado, Zarya!",
  ui_story_5061_50610602_45_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5061_50610602_46_dialog_content = "... Ai!",
  ui_story_5061_50610602_47_dialog_content = "Isso não doeu tanto quanto eu pensei que doeria.",
  ui_story_5061_50610602_48_dialog_content = "(Não... Parecia que algo nos pegou enquanto estávamos caindo...)",
  ui_story_5061_50610602_49_dialog_content = "...",
  ui_story_5061_50610602_50_dialog_content = "(Dessa forma, parece seguro o suficiente, certo?)",
  ui_story_5061_50610602_51_dialog_content = "Ei, Zarya, devemos...",
  ui_story_5061_50610602_52_dialog_content = "Ah não, ela está inconsciente...",
  ui_story_5061_50610701_1_dialog_content = "Zarya, fique em casa hoje, não vá a lugar nenhum, ok?",
  ui_story_5061_50610701_2_dialog_content = "Mas eu não saio de casa há dias...",
  ui_story_5061_50610701_3_dialog_content = "Por que você sempre quer sair? Você não tem amigos ou família para cuidar de você. Ou está planejando causar problemas com sua Luminática novamente?",
  ui_story_5061_50610701_4_dialog_content = "Lembra de como você congelou a carruagem da última vez? Coisas assim nunca podem acontecer novamente!",
  ui_story_5061_50610701_5_dialog_content = "Eu... eu entendo. Me desculpe, pai.",
  ui_story_5061_50610701_6_dialog_content = "(Outro dia solitário no meu quarto...)",
  ui_story_5061_50610701_7_dialog_content = "Ah, Zarya, olha essas flores - espera, por que você parece tão desanimado?",
  ui_story_5061_50610701_8_dialog_content = "Alina... Pai não vai me deixar sair de casa de novo hoje...",
  ui_story_5061_50610701_9_dialog_content = "... O pai está ocupado demais com o trabalho para se preocupar com qualquer outra coisa, Zarya.",
  ui_story_5061_50610701_10_dialog_content = "Ele tem medo de não estar lá para ajudar se algo acontecer com você. Ele não sabe de que outra forma protegê-lo.",
  ui_story_5061_50610701_11_dialog_content = "Eu sei... É tudo porque não consigo controlar meus Luminatics. Eu não sou nada além de um problema...",
  ui_story_5061_50610701_12_dialog_content = "Isso não é verdade, Zarya. Além disso, eu também tinha o mesmo problema. Eu até congelava a porta da frente sem querer!",
  ui_story_5061_50610701_13_dialog_content = "Eu não queria que ninguém descobrisse, por isso sempre dava um chute pra abrir primeiro! Hahaha!",
  ui_story_5061_50610701_14_dialog_content = "Pfft, você não me engana, Alina. Que tipo de capitã de patrulha não consegue controlar seus próprios poderes?",
  ui_story_5061_50610701_15_dialog_content = "Claro que posso controlá-los agora, mas você é muito mais poderoso do que eu era na sua idade.",
  ui_story_5061_50610701_16_dialog_content = "Na verdade, com habilidades como as suas, você poderia até se tornar um guarda real na corte de Queen Bethlehem!",
  ui_story_5061_50610701_17_dialog_content = "Uma guarda real...? Mas esse sempre foi o seu sonho, Alina...",
  ui_story_5061_50610701_18_dialog_content = "Mas ser um patrulheiro também é ótimo! Posso ver todos os tipos de lugares distantes, como montanhas nevadas e até mesmo fontes termais...",
  ui_story_5061_50610701_19_dialog_content = "E isso não pode ser muito pior do que servir no Tribunal, certo?",
  ui_story_5061_50610701_20_dialog_content = "Você é incrível, Alina... Você está sempre cheia de força e motivação, diferente de sua irmã inútil e deprimida.",
  ui_story_5061_50610701_21_dialog_content = "Não se preocupe, Zarya! Logo você será tão forte quanto eu... Não, ainda mais forte!",
  ui_story_5061_50610701_22_dialog_content = "Além disso, ainda não desisti do meu sonho. Tenho certeza de que me tornarei um guarda real algum dia!",
  ui_story_5061_50610701_23_dialog_content = "E quando esse dia chegar, vou proteger Northland com o Queen!",
  ui_story_5061_50610701_24_dialog_content = "Heehee! Eu sei que você consegue!",
  ui_story_5061_50610701_25_dialog_content = "Eita! Parece que fiquei conversando por tempo demais. Está quase na hora de encontrar com os outros patrulheiros!",
  ui_story_5061_50610701_26_dialog_content = "Oh não! É melhor se apressar, Alina... Boa sorte na sua missão!",
  ui_story_5061_50610701_27_dialog_content = "Obrigado. Tente manter o ânimo, tá? Lembre-se, quando o Pai estiver chateado, não leve muito a sério o que ele diz!",
  ui_story_5061_50610701_28_dialog_content = "(... E então ela se foi...)",
  ui_story_5061_50610701_29_dialog_content = "(Se eu soubesse o que aconteceria em seguida... nunca teria deixado ela partir.)",
  ui_story_5061_50610701_30_dialog_content = "(... Mas o passado nunca pode ser mudado. Na minha tristeza e arrependimento, tudo o que eu podia fazer era arriscar minha vida para consertar as coisas...)",
  ui_story_5061_50610701_31_dialog_content = "(A última localização conhecida da equipe de patrulha dela... já estava infestada de Eclipsitas...)",
  ui_story_5061_50610701_32_dialog_content = "Alina! Você está aí?!",
  ui_story_5061_50610701_33_dialog_content = "Roaaaar—",
  ui_story_5061_50610701_34_dialog_content = "Fique longe do meu caminho!",
  ui_story_5061_50610701_35_dialog_content = "Alina! Por favor, me responda!",
  ui_story_5061_50610701_36_dialog_content = "Grrrr!",
  ui_story_5061_50610701_37_dialog_content = "Mova-se!",
  ui_story_5061_50610701_38_dialog_content = "Irmã... Você... Ainda está viva? Estou tão assustada...",
  ui_story_5061_50610701_39_dialog_content = "... Não há... necessidade de temer.",
  ui_story_5061_50610701_40_dialog_content = "...!",
  ui_story_5061_50610701_41_dialog_content = "Essa voz... É você, Alina?",
  ui_story_5061_50610701_42_dialog_content = "... Você quer salvar alguém?",
  ui_story_5061_50610701_43_dialog_content = "Sim! Eu... Eu quero salvar minha irmã!",
  ui_story_5061_50610701_44_dialog_content = "... Eu reconheço seu potencial...",
  ui_story_5061_50610701_45_dialog_content = "... Com você, talvez a missão... possa ser cumprida...",
  ui_story_5061_50610701_46_dialog_content = "... Nesse caso, você assumirá... minha solidão...",
  ui_story_5061_50610701_47_dialog_content = "(E assim, segui aquela voz pela neve...)",
  ui_story_5061_50610701_48_dialog_content = "(Eu pensei que me levaria até minha irmã, mas em vez disso... Me levou a um inferno que eu nunca poderia ter imaginado.)",
  ui_story_5061_50610701_49_dialog_content = "<color=#e8d9bb>Inúmeros patrulheiros estavam caídos e imóveis no chão.</color>",
  ui_story_5061_50610701_50_dialog_content = "<color=#e8d9bb>Eclipsitas com bocas escancaradas e uma cacofonia de rugidos.</color>",
  ui_story_5061_50610701_51_dialog_content = "<color=#e8d9bb>O fedor nauseante, ainda penetrante mesmo em meio à neve que cai.</color>",
  ui_story_5061_50610701_52_dialog_content = "<color=#e8d9bb>E o pântano abismal, viscoso e repugnante no chão.</color>",
  ui_story_5061_50610701_53_dialog_content = "Isso não é real... Isso não pode ser real...",
  ui_story_5061_50610701_54_dialog_content = "Monstros imundos! Fiquem longe da minha irmã!",
  ui_story_5061_50610701_55_dialog_content = "Floresça, Geluz!",
  ui_story_5061_50610701_56_dialog_content = "Roaaaar—",
  ui_story_5061_50610701_57_dialog_content = "São muitos deles! Não consigo vencer todos!",
  ui_story_5061_50610701_58_dialog_content = "Rooooaaaar—",
  ui_story_5061_50610701_59_dialog_content = "Desculpe, Alina... Acho que não consigo matar todos esses Eclipsitas!",
  ui_story_5061_50610701_60_dialog_content = "Se eu fosse mais forte, talvez pudesse te salvar agora...",
  ui_story_5061_50610701_61_dialog_content = "Alina... Alina! Nããããão!!!",
  ui_story_5061_50610701_62_dialog_content = "<size=45>Alina!!!</size>",
  ui_story_5061_50610701_63_dialog_content = "... Zarya! Acorde!",
  ui_story_5061_50610701_64_dialog_content = "Alina!",
  ui_story_5061_50610701_65_dialog_content = "Calma, Zarya! Foi apenas um pesadelo!",
  ui_story_5061_50610701_66_dialog_content = "...",
  ui_story_5061_50610701_67_dialog_content = "Você se lembra do chão cedendo sob nós? Acho que caímos em uma caverna ou algo assim.",
  ui_story_5061_50610701_68_dialog_content = "Parece haver ruínas presas no gelo aqui embaixo. Vou dar uma olhada mais de perto...",
  ui_story_5061_50610701_69_dialog_content = "Roaaaar—",
  ui_story_5061_50610701_70_dialog_content = "Ah! E-Eclipsitas! Oh não, o que devemos fazer? Eu não consigo vencer todos eles...",
  ui_story_5061_50610701_71_dialog_content = "Por que você está em pânico? Isso tem algo a ver com o seu pesadelo?",
  ui_story_5061_50610701_72_dialog_content = "Junte-se, Zarya! Não deixe o passado atrapalhar o seu presente!",
  ui_story_5061_50610701_73_dialog_content = "Roaaaar—",
  ui_story_5061_50610701_74_dialog_content = "Onde está a Zarya que conhecíamos?! Precisamos dela agora mais do que nunca!",
  ui_story_5061_50610701_75_dialog_content = "Energia—Absorção! Rápido, por aqui!",
  ui_story_5061_50610701_76_dialog_content = "Essa voz...!",
  ui_story_5061_50610701_77_dialog_content = "Levante-se, Zarya! Precisamos sair daqui!",
  ui_story_5061_50610702_1_dialog_content = "Devemos estar seguros aqui por enquanto.",
  ui_story_5061_50610702_2_dialog_content = "Estou explorando esta área há algum tempo. Se minha intuição estiver correta, deve haver outra saída por perto, uma que leve ao resto das ruínas subterrâneas de Northland.",
  ui_story_5061_50610702_3_dialog_content = "Essas saídas costumam ser as mais perigosas quando se trata dessas ruínas.",
  ui_story_5061_50610702_4_dialog_content = "Os Eclipsitas ao redor deles estão começando a descongelar. Eles podem acordar a qualquer momento.",
  ui_story_5061_50610702_5_dialog_content = "Este gelo... É feito da mesma Luminática que o Zarya, não é?",
  ui_story_5061_50610702_6_dialog_content = "Isso mesmo. Na verdade, eu tenho motivos para acreditar que também foi produzido pela própria senhorita Zarya.",
  ui_story_5061_50610702_7_dialog_content = "Provavelmente foi o resultado explosivo do poder dela ficando fora de controle no passado.",
  ui_story_5061_50610702_8_dialog_content = "Você está dizendo... que eu fiz isso?",
  ui_story_5061_50610702_9_dialog_content = "No momento, não consigo pensar em uma resposta melhor, então sim.",
  ui_story_5061_50610702_10_dialog_content = "Para dizer a verdade, Srta. Zarya... Eu queria te perguntar algo há muito tempo, mas não conseguia encontrar as palavras certas...",
  ui_story_5061_50610702_11_dialog_content = "Isso tem algo a ver com nossa situação atual?",
  ui_story_5061_50610702_12_dialog_content = "Por favor, fale o que pensa, Sr. Antony. Esta é a segunda vez que você salva minha vida; responder às suas perguntas é o mínimo que posso fazer.",
  ui_story_5061_50610702_13_dialog_content = "Se a sua gentileza não for suficiente para me fazer aceitar a verdade...",
  ui_story_5061_50610702_14_dialog_content = "Então eu não sei o que vai.",
  ui_story_5061_50610702_15_dialog_content = "Muito bem. Vamos começar com a fonte do seu poder.",
  ui_story_5061_50610702_16_dialog_content = "Acho que agora tenho uma compreensão básica disso. A estranha Lumina presente em seu corpo se originou nessas ruínas, e parece que você recebeu esse poder por algum propósito desconhecido.",
  ui_story_5061_50610702_17_dialog_content = "Para provar meu ponto... PlayerName, você seria tão gentil em usar seus próprios poderes para analisar o gelo nessas ruínas?",
  ui_story_5061_50610702_18_dialog_content = "Ah... Claro!",
  ui_story_5061_50610702_19_option_content = "Varredura Psíquica",
  ui_story_5061_50610702_20_dialog_content = "Essas formações de gelo... Elas foram definitivamente influenciadas pelos Luminatics.",
  ui_story_5061_50610702_21_dialog_content = "Hmm? Eles estão até emitindo partículas de Lumina!",
  ui_story_5061_50610702_22_dialog_content = "Essa sensação... Não é diferente de quando senti o gelo ao redor de Zarya quando nos conhecemos pela primeira vez.",
  ui_story_5061_50610702_23_dialog_content = "Você está certo! E quando eu me aproximo para dar uma olhada...",
  ui_story_5061_50610702_24_dialog_content = "Zarya, seu cabelo...!",
  ui_story_5061_50610702_25_dialog_content = "Huh? Por que meu cabelo está brilhando de repente...?",
  ui_story_5061_50610702_26_dialog_content = "Acredito que seja um tipo de ressonância. Quando PlayerName usou seus poderes no gelo, começou a ressoar com a Lumina em seu corpo.",
  ui_story_5061_50610702_27_dialog_content = "Mas isso não é perigoso?",
  ui_story_5061_50610702_28_dialog_content = "Não posso ter certeza... Mas o perigo potencial não é nada comparado ao que estou prestes a dizer.",
  ui_story_5061_50610702_29_dialog_content = "O que é isso...?",
  ui_story_5061_50610702_30_dialog_content = "Quando ainda estávamos na superfície, baseei minha conjectura no recente fenômeno conhecido como Aurora Tempestade...",
  ui_story_5061_50610702_31_dialog_content = "Como tal, foi impossível para mim estabelecer uma linha do tempo para o incidente descrito pela Srta. Zarya. Na verdade, eu nem mesmo conseguia provar que isso realmente aconteceu.",
  ui_story_5061_50610702_32_dialog_content = "No entanto, usando o depoimento da Srta. Zarya como base para minha conjectura...",
  ui_story_5061_50610702_33_dialog_content = "Rapidamente me deparei com uma descoberta surpreendente.",
  ui_story_5061_50610702_34_dialog_content = "Ou seja, a irmã da Srta. Zarya, uma ex-capitã de patrulha e membro honorário da guarda real do Norte, conhecida como <color=#FFB400>Alina</color>...",
  ui_story_5061_50610702_35_dialog_content = "Foi uma figura proeminente que viveu <color=#FFB400>há muitas décadas atrás</color>!",
  ui_story_5061_50610702_36_dialog_content = "...",
  ui_story_5061_50610702_37_dialog_content = "Em outras palavras, a Aurorastorm que você vivenciou foi o mesmo evento de <color=#FFB400>cem anos atrás</color>.",
  ui_story_5061_50610702_38_dialog_content = "... O que?",
  ui_story_5061_50610702_39_dialog_content = "Mas...",
  ui_story_5061_50610702_40_dialog_content = "Mas isso significa... <size=45>Zarya tem <color=#FFB400>mais de cem anos</color>???</size>",
  ui_story_5061_50610801_1_dialog_content = "Ele possui mais livros do que uma biblioteca... Espere, o que é um \"rádio\"?",
  ui_story_5061_50610801_2_dialog_content = "PlayerName? Ele também menciona algo chamado \"função transmissora\". O que isso significa?",
  ui_story_5061_50610801_3_dialog_content = "Caramba, por que você tá falando igual minha avó? Ninguém assusta crianças assim hoje em dia!",
  ui_story_5061_50610801_4_dialog_content = "Na verdade, parece que você ficou preso no gelo por muito tempo.",
  ui_story_5061_50610801_5_dialog_content = "(... Finalmente entendi por que as coisas pareciam tão estranhas agora!)",
  ui_story_5061_50610801_6_dialog_content = "Mesmo que as coisas dificilmente mudem aqui em Northland, o tempo ainda é tão implacável quanto em qualquer outro lugar...)",
  ui_story_5061_50610801_7_dialog_content = "(Cem anos se passaram enquanto Zarya estava congelado no gelo...)",
  ui_story_5061_50610801_8_dialog_content = "...",
  ui_story_5061_50610801_9_dialog_content = "Não... Isso não pode ser...",
  ui_story_5061_50610801_10_dialog_content = "Você deve estar brincando, certo, Sr. Antony?",
  ui_story_5061_50610801_11_dialog_content = "Desculpe, mas essa é a verdade.",
  ui_story_5061_50610801_12_dialog_content = "A verdade...?",
  ui_story_5061_50610801_13_dialog_content = "Então a verdade... é que este mundo está um século à frente do meu tempo?",
  ui_story_5061_50610801_14_dialog_content = "Todos os meus entes queridos... minha irmã... Eles já se foram todos?",
  ui_story_5061_50610801_15_dialog_content = "E eu sou... o único que restou?",
  ui_story_5061_50610801_16_dialog_content = "Zarya...",
  ui_story_5061_50610801_17_dialog_content = "...",
  ui_story_5061_50610801_18_dialog_content = "... Eu não acredito em você!",
  ui_story_5061_50610801_19_dialog_content = "Espere, Zarya! Onde você está indo?",
  ui_story_5061_50610801_20_dialog_content = "Não se incomode em me seguir!",
  ui_story_5061_50610801_21_dialog_content = "O quê? Eu não posso simplesmente te deixar sozinho aqui!",
  ui_story_5061_50610801_22_dialog_content = "Você tem ideia de como me sinto agora? Por favor, apenas não diga mais uma palavra...",
  ui_story_5061_50610801_23_dialog_content = "Desculpe, Zarya, mas você precisa me ouvir! Eu sei exatamente como você se sente!",
  ui_story_5061_50610801_24_dialog_content = "Eu sei como é ser deixado sozinho em um lugar frio e escuro!",
  ui_story_5061_50610801_25_dialog_content = "Sei como é difícil reaparecer no mundo, apenas para descobrir que todos esqueceram de você!",
  ui_story_5061_50610801_26_dialog_content = "E... eu sei o quão doloroso é finalmente aprender mais sobre o seu passado, apenas para se encontrar de volta ao ponto de partida.",
  ui_story_5061_50610801_27_dialog_content = "...",
  ui_story_5061_50610801_28_dialog_content = "Eu... Eu sabia que tinha algo errado desde o começo...",
  ui_story_5061_50610801_29_dialog_content = "... Mas eu não quero aceitar isso! Você pode estar certo sobre meus novos poderes não serem meus...",
  ui_story_5061_50610801_30_dialog_content = "Afinal, eu sou apenas um covarde que piora tudo...",
  ui_story_5061_50610801_31_dialog_content = "Se eu fosse tão corajoso quanto você...",
  ui_story_5061_50610801_32_dialog_content = "Se eu fosse tão forte... Como você ou minha irmã... Snif...",
  ui_story_5061_50610801_33_dialog_content = "Aaaaaaaah—",
  ui_story_5061_50610801_34_dialog_content = "(Zarya...)",
  ui_story_5061_50610801_35_option_content = "Coloque a mão no ombro dela",
  ui_story_5061_50610801_36_option_content = "Abraçá-la gentilmente",
  ui_story_5061_50610801_37_dialog_content = "(... Você não está sozinho.)",
  ui_story_5061_50610801_38_dialog_content = "Você tem a gente agora, Zarya... Estamos aqui por você também.",
  ui_story_5061_50610801_39_dialog_content = "Sempre que estiver se sentindo para baixo, lembre-se... Há pelo menos mais uma pessoa no mundo que sabe como é se sentir abandonado pelo tempo.",
  ui_story_5061_50610801_40_dialog_content = "Alguém que ainda enfrenta todos os tipos de problemas para se reintegrar na sociedade...",
  ui_story_5061_50610801_41_dialog_content = "Eu...",
  ui_story_5061_50610801_42_dialog_content = "Alguém que, mesmo tendo poderes incríveis, ainda fica com as pernas congeladas ao tentar ajudar os outros em necessidade.",
  ui_story_5061_50610801_43_dialog_content = "<color=#e8d9bb>Estrondo-!!!</color>",
  ui_story_5061_50610801_44_dialog_content = "...! Que diabos foi isso?!",
  ui_story_5061_50610801_45_dialog_content = "Um crescimento anormal no gelo está causando o desabamento desta parte da caverna!",
  ui_story_5061_50610801_46_dialog_content = "Não... Isso é muito intenso para ser simplesmente descrito como \"anormal\". A ressonância entre Zarya e o gelo pode ser a causa disso...",
  ui_story_5061_50610801_47_dialog_content = "Embora também possa ser causado pelas ruínas...",
  ui_story_5061_50610801_48_dialog_content = "Precisamos chegar à saída o mais rápido possível! Podemos encontrá-la seguindo o fluxo de ar!",
  ui_story_5061_50610801_49_dialog_content = "Consegue ficar de pé, Zarya? Temos que ir!",
  ui_story_5061_50610801_50_dialog_content = "Eu... estou bem!",
  ui_story_5061_50610801_51_dialog_content = "Por aqui, PlayerName!",
  ui_story_5061_50610801_52_dialog_content = "Até as ruínas estão começando a tremer. Este lugar vai desabar a qualquer momento!",
  ui_story_5061_50610801_53_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5061_50610801_54_dialog_content = "Urg, minha perna!",
  ui_story_5061_50610801_55_dialog_content = "Você tá ferido!",
  ui_story_5061_50610801_56_dialog_content = "E-Eu só me arranhei, não se preocupe! Ainda consigo correr!",
  ui_story_5061_50610801_57_dialog_content = "Eu consigo ver a luz através do teto da caverna aqui! Estamos quase na saída, agora vamos rápido!",
  ui_story_5061_50610801_58_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5061_50610801_59_dialog_content = "Cuidado com a cabeça, PlayerName!",
  ui_story_5061_50610801_60_dialog_content = "(Um enorme pedaço de gelo está caindo bem acima de mim. A dor na minha perna me diz que não vou conseguir desviar a tempo...)",
  ui_story_5061_50610801_61_dialog_content = "(Pelo menos... Eu tenho que ajudar aqueles dois a escapar...)",
  ui_story_5061_50610801_62_option_content = "Empurre Zarya",
  ui_story_5061_50610801_63_dialog_content = "Cuidado, Zarya!",
  ui_story_5061_50610801_64_option_content = "Empurre Antony",
  ui_story_5061_50610801_65_dialog_content = "Cuidado, Antony!",
  ui_story_5061_50610801_66_dialog_content = "... Floresça, Geluz!",
  ui_story_5061_50610801_67_dialog_content = "<color=#e8d9bb>Sob o ataque de Zarya, a enorme rocha se despedaçou em pequenos pedaços e se espalhou ao redor.</color>",
  ui_story_5061_50610801_68_dialog_content = "Zarya... Você nos salvou!",
  ui_story_5061_50610801_69_dialog_content = "Eu sei... Eu sei que se minha irmã estivesse aqui agora, ela não iria querer que eu continuasse me afundando na minha tristeza...",
  ui_story_5061_50610801_70_dialog_content = "É por isso que vou usar meus Luminatics neste gelo e abrir um caminho para você.",
  ui_story_5061_50610801_71_dialog_content = "Deixarei a navegação com você! Se avistar algum Eclipsite, me diga onde estão e eu farei o que puder!",
  ui_story_5061_50610801_72_dialog_content = "Sim!",
  ui_story_5061_50610801_73_dialog_content = "Entendido. Nosso objetivo é a superfície!",
  ui_story_5061_50610802_1_dialog_content = "Já estamos bem longe do alcance protetor do Farol. Seguir em direção à saída também nos levará na direção oposta ao Farol.",
  ui_story_5061_50610802_2_dialog_content = "A partir daqui, receio que os Eclipsitas só vão aumentar em força e números.",
  ui_story_5061_50610802_3_dialog_content = "...!",
  ui_story_5061_50610802_4_dialog_content = "Eu... eu sinto algo por perto.",
  ui_story_5061_50610802_5_dialog_content = "Mais Eclipsitas?",
  ui_story_5061_50610802_6_dialog_content = "Não, não é isso.",
  ui_story_5061_50610802_7_dialog_content = "Senti uma presença quando ainda estávamos na superfície. Pelo que eu posso dizer... Pode ser um Auroriano.",
  ui_story_5061_50610802_8_dialog_content = "Um Aurorian? Em um lugar como este?",
  ui_story_5061_50610802_9_dialog_content = "Sim, é definitivamente um Aurorian, mas algo parece diferente.",
  ui_story_5061_50610802_10_dialog_content = "Deixe-me tentar usar meus poderes novamente...",
  ui_story_5061_50610802_11_option_content = "Varredura Psíquica",
  ui_story_5061_50610802_12_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610802_13_dialog_content = "Já se passaram tantos anos. Você me esqueceu durante todos esses anos.",
  ui_story_5061_50610802_14_dialog_content = "Agora, reaparecendo de repente assim, para quê? Pelo poder da <color=#FFB400>Fagulha</color>?",
  ui_story_5061_50610802_15_dialog_content = "Um século se passou. Por que eu, sendo ativado novamente, sinto tanta falta de energia enquanto vocês todos estão tão... cheios?",
  ui_story_5061_50610802_16_dialog_content = "Urgh... M-Minha cabeça...",
  ui_story_5061_50610802_17_dialog_content = "O que... Você está falando...?",
  ui_story_5061_50610802_18_dialog_content = "Respondam-me, Aurorianos da terra, condutores dispostos de Lux - receptores da bênção da Centelha!",
  ui_story_5061_50610802_19_dialog_content = "Ahh!!!",
  ui_story_5061_50610802_20_dialog_content = "(Minha cabeça está se partindo em duas... Preciso quebrar o link!)",
  ui_story_5061_50610802_21_dialog_content = "Espere, Senhorita Zarya!",
  ui_story_5061_50610802_22_dialog_content = "Você está bem, PlayerName? Ainda consegue me ver? E isso? Consegue sentir eu beliscando seus dedos?",
  ui_story_5061_50610802_23_dialog_content = "Hmm... Sim, eu posso sentir você.",
  ui_story_5061_50610802_24_dialog_content = "Bom, sua reação é normal e sua visão parece boa. Também não parece que você machucou a cabeça...",
  ui_story_5061_50610802_25_dialog_content = "Estou bem, vamos continuar. Eu senti um Aurorian perigoso agora há pouco... Espere, ela...",
  ui_story_5061_50610802_26_dialog_content = "<size=45>... Ela está vindo!!</size>",
  ui_story_5061_50610802_27_dialog_content = "<color=#e8d9bb>Ampliação!</color>",
  ui_story_5061_50610802_28_dialog_content = "Urgh! M-Meu corpo...",
  ui_story_5061_50610802_29_dialog_content = "O que é isso? Eu... Eu não consigo controlar o fluxo do meu Lumina!",
  ui_story_5061_50610802_30_dialog_content = "Meu corpo está tão pesado...",
  ui_story_5061_50610802_31_dialog_content = "Está consumindo toda a minha força só para ficar de pé...",
  ui_story_5061_50610802_32_dialog_content = "Espere aí...",
  ui_story_5061_50610802_33_dialog_content = "O seu Lumina... E até mesmo o Lumina das ruínas... Tudo está sendo sugado na mesma direção!",
  ui_story_5061_50610901_1_dialog_content = "<color=#e8d9bb>No ponto final do fluxo de Lumina, surge uma figura em branco imaculado.</color>",
  ui_story_5061_50610901_2_dialog_content = "<color=#e8d9bb>O corpo dela paira no centro do espaço, irradiando uma sensação etérea de ausência de peso, com a luz celestial na saída servindo como pano de fundo.</color>",
  ui_story_5061_50610901_3_dialog_content = "<color=#e8d9bb>Enquanto ela se move graciosamente com aqueles intrincados membros mecânicos, toda a ruína parece despertar, emitindo brilho e ressoando com ela.</color>",
  ui_story_5061_50610901_4_dialog_content = "Olha Você aqui.",
  ui_story_5061_50610901_5_dialog_content = "Você é... Um auroriano?",
  ui_story_5061_50610901_6_dialog_content = "Eu sou... o gerente e guardião das ruínas, No. 33.",
  ui_story_5061_50610901_7_dialog_content = "Para cumprir a missão, é necessário recuperar a energia.",
  ui_story_5061_50610901_8_dialog_content = "Suas ações... ultrapassaram os limites de defesa.",
  ui_story_5061_50610901_9_dialog_content = "Seu jeito de falar...",
  ui_story_5061_50610901_10_dialog_content = "O quê, Celestita, você pretende usar seus poderes em mim, o que acionará meu contra-ataque defensivo?",
  ui_story_5061_50610901_11_dialog_content = "(Aquela sensação de ter minha mente perfurada... Será que foi o \"contra-ataque defensivo\" dela?)",
  ui_story_5061_50610901_12_dialog_content = "Cuidado, PlayerName. Eu posso sentir que tem algo errado com ela.",
  ui_story_5061_50610901_13_dialog_content = "É como se... algo nela estivesse quebrado.",
  ui_story_5061_50610901_14_dialog_content = "Ah, você, a garota com poderes especiais de Lúmina. Você me causou muitos problemas...",
  ui_story_5061_50610901_15_dialog_content = "Eu? O que eu fiz?",
  ui_story_5061_50610901_16_dialog_content = "Como o bloco de energia reserva para a <color=#FFB400>Centelha</color>...",
  ui_story_5061_50610901_17_dialog_content = "Aqui, a ordem do fluxo de Lumina, suave e ininterrupta, é crucial!",
  ui_story_5061_50610901_18_dialog_content = "Sua forte capacidade de absorção perturba todo o sistema, fazendo com que meu trabalho de reparo falhe repetidamente.",
  ui_story_5061_50610901_19_dialog_content = "... Habilidade de absorção?",
  ui_story_5061_50610901_20_dialog_content = "Entendi. Isso pode explicar por que seu cabelo mudou de cor, Srta. Zarya.",
  ui_story_5061_50610901_21_dialog_content = "Mas se você é o guardião deste lugar, por que há Eclipsitas circulando livremente por toda parte?",
  ui_story_5061_50610901_22_dialog_content = "\"Em todos os lugares\"? Não existe esse conceito. Eu só tenho \"aqui.\"",
  ui_story_5061_50610901_23_dialog_content = "Conectado a mim, essa instalação é tudo para mim...",
  ui_story_5061_50610901_24_dialog_content = "Minha missão... é <color=#FFB400>manter o equilíbrio do Lumina aqui</color>. Todo o resto não está relacionado.",
  ui_story_5061_50610901_25_dialog_content = "O que você tá planejando?",
  ui_story_5061_50610901_26_dialog_content = "Isso não é da sua conta, forasteiro. Eu preciso eliminar ela e recuperar a Lumina que ela roubou...",
  ui_story_5061_50610901_27_dialog_content = "A Lumina... que eu roubei? O que você quer dizer com isso?",
  ui_story_5061_50610901_28_dialog_content = "Comando: Destruir.",
  ui_story_5061_50610901_29_dialog_content = "Cuidado!",
  ui_story_5061_50610901_30_dialog_content = "Pare! Ainda podemos conversar e resolver isso!",
  ui_story_5061_50610901_31_dialog_content = "Tarde demais... Já faz muito tempo...",
  ui_story_5061_50610901_32_dialog_content = "Não vou perder meu tempo esperando... e tentando.",
  ui_story_5061_50610901_33_dialog_content = "Já que você não vai cumprir minhas instruções, só posso recorrer ao uso da força...",
  ui_story_5061_50610901_34_dialog_content = "Preparem-se para a batalha, todos!",
  ui_story_5061_50610902_1_dialog_content = "... Cobertura, Lâmina de Gelo!",
  ui_story_5061_50610902_2_dialog_content = "Ataque Ambiental!",
  ui_story_5061_50610902_3_dialog_content = "Nossos ataques não são fortes o suficiente!",
  ui_story_5061_50610902_4_dialog_content = "Não podemos machucá-la enquanto nosso Lumina estiver sendo drenado de nossos corpos...",
  ui_story_5061_50610902_5_dialog_content = "Cuidado, PlayerName! Ela está atacando!",
  ui_story_5061_50610902_6_dialog_content = "Urgh! ... Te peguei.",
  ui_story_5061_50610902_7_dialog_content = "Antony!",
  ui_story_5061_50610902_8_dialog_content = "Não se preocupe comigo. Minha Lumina pode não ser tão poderosa quanto a da Srta. Zarya, mas minha força física é confiável o suficiente.",
  ui_story_5061_50610902_9_dialog_content = "(... Não há mesmo nenhuma outra maneira?)",
  ui_story_5061_50610902_10_dialog_content = "(Eles têm me protegido todo esse tempo... Será que realmente não há nada que eu possa fazer para ajudar?)",
  ui_story_5061_50610902_11_dialog_content = "(Talvez se eu tentar usar meus poderes novamente... Conseguirei encontrar o ponto fraco dela!)",
  ui_story_5061_50610902_12_option_content = "Aumento de Força",
  ui_story_5061_50610902_13_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610902_14_dialog_content = "Urgh—Minha cabeça!",
  ui_story_5061_50610902_15_dialog_content = "Pare com isso, PlayerName!",
  ui_story_5061_50610902_16_dialog_content = "A mente dela está protegida dos seus poderes psíquicos! Você só vai se machucar se usá-los!",
  ui_story_5061_50610902_17_dialog_content = "E-eu não posso deixar vocês fazerem toda a luta... É por isso que vou ajudar do único jeito que eu posso...",
  ui_story_5061_50610902_18_option_content = "Aumento de Força",
  ui_story_5061_50610902_19_dialog_content = "Se houver uma maneira de contornar as defesas dela, então talvez eu possa—",
  ui_story_5061_50610902_20_dialog_content = "Argh...! Minha cabeça está prestes a explodir!",
  ui_story_5061_50610902_21_dialog_content = "Droga... Mesmo que eu o segure, não consigo impedir PlayerName de usar seus poderes.",
  ui_story_5061_50610902_22_dialog_content = "Já chega! Só pare!",
  ui_story_5061_50610902_23_dialog_content = "Você não pode continuar se machucando assim, PlayerName!",
  ui_story_5061_50610902_24_dialog_content = "Isso vale pra você também, Sr. Antony!",
  ui_story_5061_50610902_25_dialog_content = "Eu... Eu devo minha vida a vocês dois. Não suporto mais ver vocês se machucarem.",
  ui_story_5061_50610902_26_dialog_content = "Vocês são boas pessoas e ainda têm objetivos a perseguir na vida.",
  ui_story_5061_50610902_27_dialog_content = "Espere, Zarya, o que você quer dizer com isso...?",
  ui_story_5061_50610902_28_dialog_content = "Perdi minha irmã, minha família e a vida que eu costumava ter...",
  ui_story_5061_50610902_29_dialog_content = "Não tenho mais para onde ir, nenhum lugar para chamar de \"lar\"... Sou apenas uma casca vazia da pessoa que eu era antes.",
  ui_story_5061_50610902_30_dialog_content = "É por isso que eu não me importo com o que acontece comigo agora.",
  ui_story_5061_50610902_31_dialog_content = "Mas pelo menos vocês dois—",
  ui_story_5061_50610902_32_dialog_content = "Que diabos você pensa que está fazendo, Zarya?!",
  ui_story_5061_50610902_33_dialog_content = "<color=#e8d9bb>Crocante—</color>",
  ui_story_5061_50610902_34_dialog_content = "Espere, Zarya—!",
  ui_story_5061_50610902_35_dialog_content = "Você deve viver.",
  ui_story_5061_50610902_36_dialog_content = "Zarya!!!",
  ui_story_5061_50610902_37_dialog_content = "<size=45>Zaryaaaaaaaa!!!</size>",
  ui_story_5061_50611001_1_dialog_content = "(Zarya usou uma coluna de gelo para nos levar em segurança para fora...)",
  ui_story_5061_50611001_2_dialog_content = "(Pouco tempo depois, a saída da caverna desabou completamente.)",
  ui_story_5061_50611001_3_dialog_content = "Por que... Por que eu não percebi isso antes?!",
  ui_story_5061_50611001_4_dialog_content = "Não... Isso não pode ser...",
  ui_story_5061_50611001_5_dialog_content = "Se eu fosse tão forte... Como você ou minha irmã... Snif...",
  ui_story_5061_50611001_6_dialog_content = "Aaaaaaaaaaa—",
  ui_story_5061_50611001_7_dialog_content = "Você deve viver.",
  ui_story_5061_50611001_8_dialog_content = "Se eu fosse tão forte quanto você...",
  ui_story_5061_50611001_9_dialog_content = "No momento em que Zarya soube a verdade, ela perdeu toda a esperança em seu coração.",
  ui_story_5061_50611001_10_dialog_content = "Ela mal disse uma palavra depois disso. Ela apenas nos seguiu enquanto corríamos e lutávamos para sair...",
  ui_story_5061_50611001_11_dialog_content = "Desculpe. Eu também deveria ter percebido que algo estava errado.",
  ui_story_5061_50611001_12_dialog_content = "Ela está sozinha lá dentro, presa nas ruínas sem saída... E é exatamente isso que ela quer.",
  ui_story_5061_50611001_13_dialog_content = "... Precisamos voltar e salvá-la, mas como? Eu não consigo lutar como vocês, e meus poderes psíquicos só dão errado para mim.",
  ui_story_5061_50611001_14_dialog_content = "Não só isso... No. 33 vai apenas drenar seu Lumina se lutarmos contra ela novamente! O que devemos fazer?!",
  ui_story_5061_50611001_15_dialog_content = "Pelo menos por enquanto, podemos confiar que a força da Srta. Zarya não vai falhar tão cedo. Ela não vai cair sem lutar.",
  ui_story_5061_50611001_16_dialog_content = "Mesmo com sua Lumina sendo drenada na batalha, ela ainda tinha energia suficiente para gerar uma coluna de gelo e nos levar para um lugar seguro.",
  ui_story_5061_50611001_17_dialog_content = "Além disso... Alguém disposto a se aventurar em um lugar perigoso por conta própria não desistirá de sua vida tão facilmente.",
  ui_story_5061_50611001_18_dialog_content = "Então, há algo que possamos fazer para ajudar Zarya agora mesmo?",
  ui_story_5061_50611001_19_dialog_content = "...Há.",
  ui_story_5061_50611001_20_dialog_content = "Este lugar fica muito além da fronteira noroeste de Northland, mas com sua ajuda, devemos ficar bem.",
  ui_story_5061_50611001_21_dialog_content = "O que voce precisa que eu faca?",
  ui_story_5061_50611001_22_dialog_content = "Preciso que você encontre o coelho mais próximo de nós.",
  ui_story_5061_50611001_23_dialog_content = "Um coelho?",
  ui_story_5061_50611001_24_dialog_content = "Correto. É um animal branco e fofo de mais ou menos esse tamanho, com orelhas compridas e—",
  ui_story_5061_50611001_25_dialog_content = "Eu sei o que é um coelho, Antony. Só não sei por que você precisa de um agora.",
  ui_story_5061_50611001_26_dialog_content = "Ah, é? Então você não deve ter problemas para encontrar um!",
  ui_story_5061_50611001_27_dialog_content = "Deve haver um a sudeste... Mas não consigo dizer o quão longe está. Acha que pode me dar uma mão?",
  ui_story_5061_50611001_28_dialog_content = "(... Acho que vou ter que fazer o que ele diz por enquanto.)",
  ui_story_5061_50611001_29_option_content = "Aumento de Força",
  ui_story_5061_50611001_30_dialog_content = "(Para o sudeste, né? Espere... Zarya e eu não vimos um coelho no caminho até aqui?)",
  ui_story_5061_50611001_31_dialog_content = "(... Nós conseguimos! E está bem ali!)",
  ui_story_5061_50611001_32_dialog_content = "(O coelho parece ter notado algo também. Ele está olhando na nossa direção.)",
  ui_story_5061_50611001_33_dialog_content = "Encontrei um, Antony.",
  ui_story_5061_50611001_34_dialog_content = "S-Sério? Foi rápido! Suas habilidades psíquicas são realmente impressionantes!",
  ui_story_5061_50611001_35_dialog_content = "Heh... Eles estão bem, eu acho...",
  ui_story_5061_50611001_36_dialog_content = "De qualquer forma, devemos ir.",
  ui_story_5061_50611001_37_dialog_content = "Aqui!",
  ui_story_5061_50611001_38_dialog_content = "Excelente! Se eu não estou enganado, esse coelho é um dos companheiros <color=#FFB400>dele</color>.",
  ui_story_5061_50611001_39_dialog_content = "Olá, meu pequeno amigo! Você poderia nos ajudar a enviar uma mensagem ao seu mestre, o <color=#FFB400>espírito da montanha</color>? Por favor, diga a ele que encontramos um conjunto esquecido de ruínas aqui, bem como um cidadão há muito perdido de Northland.",
  ui_story_5061_50611001_40_dialog_content = "<color=#e8d9bb>O coelho salta para longe, bem longe, na direção de Northland.</color>",
  ui_story_5061_50611001_41_dialog_content = "Um \"conjunto esquecido de ruínas\"... Você acha que tem algo a ver com a \"<color=#FFB400>Faísca</color>\" que o Aurorian mencionou anteriormente?",
  ui_story_5061_50611001_42_dialog_content = "Acredito que sim. Se o que ela diz é verdade, essas ruínas servem como fonte de energia para a Spark.",
  ui_story_5061_50611001_43_dialog_content = "A Fagulha, por sua vez, alimenta as defesas do nosso reino. Como tal, essas ruínas são as mais importantes de toda Northland.",
  ui_story_5061_50611001_44_dialog_content = "O <color=#FFB400>Farol</color>, que projeta a barreira que protege todo o nosso reino dos Eclipsitas, também faz parte da Faísca.",
  ui_story_5061_50611001_45_dialog_content = "Isso significa que o guardião louco que encontramos também faz parte das defesas de Northland?",
  ui_story_5061_50611001_46_dialog_content = "Acredito que apenas o Queen e o espírito da montanha têm acesso a esse conhecimento.",
  ui_story_5061_50611002_1_dialog_content = "Eu nunca vou desistir!",
  ui_story_5061_50611002_2_dialog_content = "(Não tenho Lumina suficiente para machucá-la...)",
  ui_story_5061_50611002_3_dialog_content = "(Também... Não só ela parece diferente dos outros aurorianos, mas suas ações e padrões de fala são realmente estranhos também...)",
  ui_story_5061_50611002_4_dialog_content = "Eu estava querendo te perguntar algo...",
  ui_story_5061_50611002_5_dialog_content = "Por que... Por que sua voz soa exatamente como a da minha irmã?!",
  ui_story_5061_50611002_6_dialog_content = "Minha voz...",
  ui_story_5061_50611002_7_dialog_content = "A voz da senhorita Alina...",
  ui_story_5061_50611002_8_dialog_content = "Você sabe quem ela é?! Me diga, o que você fez com minha irmã?!",
  ui_story_5061_50611002_9_dialog_content = "Conheci ela pessoalmente... Fiz um pacto temporário...",
  ui_story_5061_50611002_10_dialog_content = "Torne-se um recipiente de energia para executar o protocolo de limpeza máxima e dispersar os Eclipsitas...",
  ui_story_5061_50611002_11_dialog_content = "...Como assim?",
  ui_story_5061_50611002_12_dialog_content = "Alina esteve aqui uma vez... e ela me encontrou.",
  ui_story_5061_50611002_13_dialog_content = "O lado de fora estava infestado de Eclipsitas e a energia dela estava esgotada... Eu não posso sair...",
  ui_story_5061_50611002_14_dialog_content = "Uma situação terrível. Alina, ela absorveu toda a energia daqui e se tornou o receptáculo. A única solução...",
  ui_story_5061_50611002_15_dialog_content = "Então, para derrotar os Eclipsitas... Você transformou minha irmã em um recipiente para a Lúmina dessas ruínas?",
  ui_story_5061_50611002_16_dialog_content = "Mas o corpo de um Auroriano não pode conter tanta Lumina assim... Pode?",
  ui_story_5061_50611002_17_dialog_content = "Não pode... Ela sabia que sacrificaria sua vida. Não havia outra saída.",
  ui_story_5061_50611002_18_dialog_content = "... Tudo bem. Não temos mais opções.",
  ui_story_5061_50611002_19_dialog_content = "Você realmente pensou bem nisso?",
  ui_story_5061_50611002_20_dialog_content = "Você protegeu este lugar por tanto tempo... Mas agora é hora de um de nós proteger você.",
  ui_story_5061_50611002_21_dialog_content = "Não apenas isso... Mas eu também quero proteger nosso mundo pelo bem da minha irmã.",
  ui_story_5061_50611002_22_dialog_content = "Admiro sua coragem. Vamos começar...",
  ui_story_5061_50611002_23_dialog_content = "Obrigado... Espírito da Aurora. Deixo o resto em suas mãos agora.",
  ui_story_5061_50611002_24_dialog_content = "Mas eu...",
  ui_story_5061_50611002_25_dialog_content = "Mas eu espero que você possa sobreviver.",
  ui_story_5061_50611002_26_dialog_content = "Meu primeiro amigo Aurorian da superfície.",
  ui_story_5061_50611002_27_dialog_content = "Cálculo... iniciando cálculo...",
  ui_story_5061_50611002_28_dialog_content = "O método para garantir sua sobrevivência...",
  ui_story_5061_50611002_29_dialog_content = "É realmente assim... que minha irmã se sacrificou?",
  ui_story_5061_50611002_30_dialog_content = "... Urgh... Alina... Alina...",
  ui_story_5061_50611002_31_dialog_content = "Erro no Modelo Eco!",
  ui_story_5061_50611002_32_dialog_content = "Tentando reiniciar.",
  ui_story_5061_50611002_33_dialog_content = "Para proteger todos da Aurora Tempestade... para me proteger...",
  ui_story_5061_50611101_1_dialog_content = "Erro no Modelo Eco!",
  ui_story_5061_50611101_2_dialog_content = "Reiniciar, erro; reiniciar, erro; reiniciar—",
  ui_story_5061_50611101_3_dialog_content = "Aviso: Intrusos detectados dentro da instalação;",
  ui_story_5061_50611101_4_dialog_content = "Eliminar, eliminar;",
  ui_story_5061_50611101_5_dialog_content = "O que está acontecendo? Ei! Ainda não terminamos de conversar!",
  ui_story_5061_50611101_6_dialog_content = "Por que isso está acontecendo com você de repente de novo? Você precisa que eu te esfrie de novo?!",
  ui_story_5061_50611101_7_dialog_content = "Proteger este lugar, minha única missão;",
  ui_story_5061_50611101_8_dialog_content = "Tudo o mais, irrelevante, eliminar;",
  ui_story_5061_50611101_9_dialog_content = "Do que você está falando?!",
  ui_story_5061_50611101_10_dialog_content = "Você não disse que protegeu todos com a ajuda da minha irmã?",
  ui_story_5061_50611101_11_dialog_content = "Não me diga que você esqueceu?!",
  ui_story_5061_50611101_12_dialog_content = "Modelo reiniciado... Encontrado erro desconhecido;",
  ui_story_5061_50611101_13_dialog_content = "Venham, todos.",
  ui_story_5061_50611101_14_dialog_content = "Devemos descer o mais leve possível...",
  ui_story_5061_50611101_15_dialog_content = "Consigo ver o fundo!",
  ui_story_5061_50611101_16_dialog_content = "Olha! É a Senhorita Zarya!",
  ui_story_5061_50611101_17_dialog_content = "Zarya! Nós voltamos para te salvar!",
  ui_story_5061_50611101_18_dialog_content = "O quê...? Por quê? Você faz ideia do quão difícil foi tirar você daqui?!",
  ui_story_5061_50611101_19_dialog_content = "Eu já te disse antes! Você não está mais sozinho!",
  ui_story_5061_50611101_20_dialog_content = "Você... Eu não posso... Ah, o que devo fazer com você?!",
  ui_story_5061_50611101_21_dialog_content = "Ficaremos bem! Além disso, já bolamos um plano!",
  ui_story_5061_50611101_22_dialog_content = "... Um plano?",
  ui_story_5061_50611101_23_dialog_content = "Você não percebeu que seu Lumina não está mais sendo drenado?",
  ui_story_5061_50611101_24_dialog_content = "... Você está certo!",
  ui_story_5061_50611101_25_dialog_content = "Agora, tudo o que precisamos fazer é limitar os movimentos de No. 33.",
  ui_story_5061_50611101_26_dialog_content = "Assim que fizermos isso, vou esperar o momento certo para usar meus poderes nela!",
  ui_story_5061_50611101_27_dialog_content = "Você enlouqueceu, PlayerName?! Já esqueceu o que isso faz com você?!",
  ui_story_5061_50611101_28_dialog_content = "O <color=#FFB400>Echo Template</color> do No. 33 continua produzindo erros devido aos danos sofridos e à sua ativação não ortodoxa.",
  ui_story_5061_50611101_29_dialog_content = "O único que pode reparar o Modelo de Eco dela é PlayerName, e somente usando seus poderes.",
  ui_story_5061_50611101_30_dialog_content = "Também temos a proteção <color=#FFB400>dele</color>, então não devemos encontrar mais resistência.",
  ui_story_5061_50611101_31_dialog_content = "Você está pronto, Zarya?",
  ui_story_5061_50611101_32_dialog_content = "... Sim. Eu acredito em você!",
  ui_story_5061_50611101_33_dialog_content = "Vamos nessa!",
  ui_story_5061_50611102_1_dialog_content = "Ela está diminuindo a velocidade!",
  ui_story_5061_50611102_2_dialog_content = "Tô pronto.",
  ui_story_5061_50611102_3_dialog_content = "Não há mais nada a temer.",
  ui_story_5061_50611102_4_dialog_content = "—!",
  ui_story_5061_50611102_5_dialog_content = "Faça isso, PlayerName!",
  ui_story_5061_50611102_6_option_content = "Aumento de Força",
  ui_story_5061_50611102_7_dialog_content = "(...!)",
  ui_story_5061_50611102_8_dialog_content = "(Eu nunca senti algo assim antes...)",
  ui_story_5061_50611102_9_dialog_content = "(Minha consciência... Ela continua avançando...)",
  ui_story_5061_50611102_10_dialog_content = "(No mundo real, tudo isso está acontecendo em um único momento, mas parece que minha mente está flutuando infinitamente por um mar de tempo—)",
  ui_story_5061_50611201_1_dialog_content = "<color=#e8d9bb>Há ████ anos, a Instalação de Fornecimento de Energia Spark Nº ███.</color>",
  ui_story_5061_50611201_2_dialog_content = "A lente auxiliar desviou pela 4682ª vez; a distância focal precisa ser recalibrada.",
  ui_story_5061_50611201_3_dialog_content = "...",
  ui_story_5061_50611201_4_dialog_content = "Calibragem falhou. Motivo: Dano irreparável no suporte auxiliar da lente nº 44.",
  ui_story_5061_50611201_5_dialog_content = "Solução: Substitua-o pelo suporte de backup Nº 863.",
  ui_story_5061_50611201_6_dialog_content = "... Componentes danificados substituídos. Estoque restante: 3264 unidades.",
  ui_story_5061_50611201_7_dialog_content = "Inspeção concluída; nenhuma anomalia encontrada. Manutenção de rotina de hoje também concluída.",
  ui_story_5061_50611201_8_dialog_content = "<color=#e8d9bb>No. 33 é encarregado de manter diversos dispositivos dentro da pequena instalação em que se encontra, especialmente o Concentrador de Lúmina.</color>",
  ui_story_5061_50611201_9_dialog_content = "<color=#e8d9bb>Desde o seu despertar dentro da instalação, ela tem se dedicado diligentemente ao trabalho de manutenção, executando fielmente sua missão atribuída.</color>",
  ui_story_5061_50611201_10_dialog_content = "O Conduto de Lumina encontrou um bloqueio pela 78.643ª vez e precisa ser desobstruído.",
  ui_story_5061_50611201_11_dialog_content = "... Tentativa de liberação falhou. Motivo: Dano irreparável na interface da tubulação do conduto 65.",
  ui_story_5061_50611201_12_dialog_content = "Solução: Substitua pela tubulação reserva 264; Estoque restante: 0 unidades.",
  ui_story_5061_50611201_13_dialog_content = "Procure por tubulações alternativas para uso. Tubulação 195, estoque: 0 unidades; Tubulação 236, estoque: 0 unidades.",
  ui_story_5061_50611201_14_dialog_content = "Não há tubulações de reposição disponíveis; Procurando tubulações em uso adequadas para substituição...",
  ui_story_5061_50611201_15_dialog_content = "Encontrada uma tubulação adequada na interface do ramal 80, com taxa de degradação de 39%. Preparando para remoção e substituição na interface 65.",
  ui_story_5061_50611201_16_dialog_content = "... Componente danificado substituído.",
  ui_story_5061_50611201_17_dialog_content = "Sistema opera normalmente, saída de energia: 60%.",
  ui_story_5061_50611201_18_dialog_content = "...",
  ui_story_5061_50611201_19_dialog_content = "(... Para substituir os componentes do Concentrador de Lumina, todos os dispositivos ao redor foram desmontados...)",
  ui_story_5061_50611201_20_dialog_content = "<color=#e8d9bb>Mas No. 33 não é apenas uma máquina; ela é uma Aurorian com seu corpo e órgãos significativamente modificados.</color>",
  ui_story_5061_50611201_21_dialog_content = "<color=#e8d9bb>Com o passar do tempo, ela também experimentaria a solidão, cansando-se da vida inalterada dentro da instalação subterrânea.</color>",
  ui_story_5061_50611201_22_dialog_content = "<color=#e8d9bb>E então, ela começou a questionar o propósito de sua própria missão.</color>",
  ui_story_5061_50611201_23_dialog_content = "... Devido à remoção das fontes de energia reserva, o sistema de aquecimento está inativo há 436 dias.",
  ui_story_5061_50611201_24_dialog_content = "(Deve estar bem frio agora... mas eu não consigo mais sentir...)",
  ui_story_5061_50611201_25_dialog_content = "(... Tudo o que eu fiz realmente tem significado?)",
  ui_story_5061_50611201_26_dialog_content = "(Já se passaram tantos anos, e ninguém nunca veio aqui ou sabe o que eu tenho feito.)",
  ui_story_5061_50611201_27_dialog_content = "(Ainda há necessidade de minha missão continuar?)",
  ui_story_5061_50611201_28_dialog_content = "Procure por módulos alternativos de armazenamento de dados que possam substituir o atual em uso.",
  ui_story_5061_50611201_29_dialog_content = "Nenhum módulo de armazenamento não utilizado. Procure por módulos substituíveis em uso ativo...",
  ui_story_5061_50611201_30_dialog_content = "Dispositivo de manutenção biológica do No. 33, cabeça, Módulo de Armazenamento 2, com taxa de degradação de 32%.",
  ui_story_5061_50611201_31_dialog_content = "(No. 33... Hã?)",
  ui_story_5061_50611201_32_dialog_content = "(Minha... cabeça? Meu... módulo de armazenamento?)",
  ui_story_5061_50611201_33_dialog_content = "...",
  ui_story_5061_50611201_34_dialog_content = "(Bem, a essa altura, do que há para se arrepender?)",
  ui_story_5061_50611201_35_dialog_content = "(... Eu já removi muitas partes antes de qualquer maneira. Meus sentidos já não são mais como os de um Auroriano vivo...)",
  ui_story_5061_50611201_36_dialog_content = "... Componentes danificados substituídos. Sistema opera normalmente, saída de energia: 19%.",
  ui_story_5061_50611201_37_dialog_content = "(Apesar da baixa produção de energia, não houve desastres ou acidentes.)",
  ui_story_5061_50611201_38_dialog_content = "(Além daqui, há várias outras instalações em funcionamento.)",
  ui_story_5061_50611201_39_dialog_content = "(Comigo ou sem mim, não faz muita diferença.)",
  ui_story_5061_50611201_40_dialog_content = "(... Será que este lugar... ainda tem um propósito?)",
  ui_story_5061_50611201_41_dialog_content = "<color=#e8d9bb>À medida que seus componentes de sustentação da vida são gradualmente desmontados, No. 33 deve entrar em períodos prolongados de hibernação para preservar suas funções de sobrevivência.</color>",
  ui_story_5061_50611201_42_dialog_content = "<color=#e8d9bb>Ela acordaria novamente em alguns anos; depois, a próxima vez seria mais de uma década depois, e então várias décadas depois...</color>",
  ui_story_5061_50611201_43_dialog_content = "<color=#e8d9bb>Há 100 anos, a Instalação de Fornecimento de Energia Spark Nº ███.</color>",
  ui_story_5061_50611201_44_dialog_content = "<color=#e8d9bb><size=45>Estrondo—</size></color>",
  ui_story_5061_50611201_45_dialog_content = "(O que... O que está acontecendo!)",
  ui_story_5061_50611201_46_dialog_content = "(Ugh... Acordando da hibernação, minha cabeça dói... Diagnóstico de emergência!)",
  ui_story_5061_50611201_47_dialog_content = "(O reservatório de energia sofreu danos irreparáveis; Lumina de alta pureza está se dispersando, causando uma <color=#FFB400>explosão de energia</color> na superfície;)",
  ui_story_5061_50611201_48_dialog_content = "(Por que, de todos os componentes, é o reservatório de energia? É a parte mais robusta do concentrador... como poderia ser danificado...)",
  ui_story_5061_50611201_49_dialog_content = "(... Ah, certo... porque já faz tanto tempo... tempo suficiente para tudo se deteriorar...)",
  ui_story_5061_50611201_50_dialog_content = "(... Quantos anos já se passaram? Não consigo me lembrar com alguns dos módulos de armazenamento perdidos...)",
  ui_story_5061_50611201_51_dialog_content = "Roaaaar—",
  ui_story_5061_50611201_52_dialog_content = "(Eclipsitas estão aqui?... Certo, os sistemas de defesa falharam há muito tempo...)",
  ui_story_5061_50611201_53_dialog_content = "(... Tudo aqui... está danificado...)",
  ui_story_5061_50611201_54_dialog_content = "(Ahhhh... finalmente... tudo está chegando ao fim...)",
  ui_story_5061_50611201_55_dialog_content = "(Nos últimos momentos, ninguém ainda está ciente de tudo que fiz ao longo dos anos...)",
  ui_story_5061_50611201_56_dialog_content = "(Já aceitei há muito tempo meu destino de desmoronar junto com este lugar...)",
  ui_story_5061_50611201_57_dialog_content = "(Ainda assim, ninguém sabe da minha existência, ninguém está ciente das contribuições que fiz...)",
  ui_story_5061_50611201_58_dialog_content = "(Qualquer um serve... pelo menos, venha... e lance um olhar sobre mim...)",
  ui_story_5061_50611201_59_dialog_content = "(Alguém...)",
  ui_story_5061_50611201_60_dialog_content = "Onde estou...?",
  ui_story_5061_50611201_61_dialog_content = "!",
  ui_story_5061_50611201_62_dialog_content = "Hmm? Você é... um auroriano?",
  ui_story_5061_50611201_63_dialog_content = "—",
  ui_story_5061_50611201_64_dialog_content = "(Meu Echo Template não pode mais me ajudar a fazer sons. Então, só posso estender minha mão instintivamente...)",
  ui_story_5061_50611201_65_dialog_content = "(Estendo a mão para aquela que me salvou da solidão infinita — Miss Alina.)",
  ui_story_5061_50611201_66_dialog_content = "(Usei uma \"parte\" da Miss Alina para consertar meu Echo Template, permitindo-me fazer sons...)",
  ui_story_5061_50611201_67_dialog_content = "(Eu conto a ela sobre minha missão, e ela me fala sobre o que aconteceu na superfície.)",
  ui_story_5061_50611201_68_dialog_content = "(A explosão de energia causada pelo mau funcionamento do Concentrador de Lumina é chamada de <color=#FFB400>Aurorastorm</color> por aqueles do lado de fora.)",
  ui_story_5061_50611201_69_dialog_content = "A Lumina anormal produzida pela Aurorastorm atraiu um grande número de Eclipsitas.",
  ui_story_5061_50611201_70_dialog_content = "(A deterioração da instalação... resulta em anormalidades na Lúmina externa, Eclipsitas correndo desenfreados e colocando em perigo a sobrevivência dos Aurorianos na superfície.)",
  ui_story_5061_50611201_71_dialog_content = "(Sempre achei que minha missão fosse manter os dispositivos funcionando.)",
  ui_story_5061_50611201_72_dialog_content = "(No entanto, na verdade, será meu verdadeiro propósito manter o ambiente para a sobrevivência dos Aurorianos?)",
  ui_story_5061_50611201_73_dialog_content = "Desculpe, mas não posso sair deste lugar. Desconectar pode resultar em uma instabilidade ainda mais grave na instalação.",
  ui_story_5061_50611201_74_dialog_content = "Mesmo que a condição das instalações não me preocupe mais, não quero que o mundo lá fora enfrente desastres ainda mais terríveis do que já enfrenta.",
  ui_story_5061_50611201_75_dialog_content = "Não há realmente outra maneira?",
  ui_story_5061_50611201_76_dialog_content = "... Com o equipamento aqui, posso concentrar a Lúmina que irrompe aqui em você, permitindo que você libere essa energia nos Eclipsitas lá fora...",
  ui_story_5061_50611201_77_dialog_content = "Dessa forma, você pode repelir o enxame de Eclipsitas e impedir a expansão da Tempestade Auroriana.",
  ui_story_5061_50611201_78_dialog_content = "Mas o corpo de um Auroriano não consegue suportar uma quantidade tão grande de energia, o que significa que você provavelmente se desintegraria em poucos minutos.",
  ui_story_5061_50611201_79_dialog_content = "(A única luz que eu ansiava durante todo esse tempo, será que vou realmente mandá-la embora com minhas próprias mãos...)",
  ui_story_5061_50611201_80_dialog_content = "... Tudo bem. Não temos mais opções.",
  ui_story_5061_50611201_81_dialog_content = "(Por favor, eu imploro, não se sacrifique. Você é a luz que eu esperava tão ansiosamente para ver.)",
  ui_story_5061_50611201_82_dialog_content = "Você realmente pensou bem nisso?",
  ui_story_5061_50611201_83_dialog_content = "Você protegeu este lugar por tanto tempo... Mas agora é hora de um de nós proteger você.",
  ui_story_5061_50611201_84_dialog_content = "Não apenas isso... Mas eu também quero proteger nosso mundo pelo bem da minha irmã.",
  ui_story_5061_50611201_85_dialog_content = "(Não... Eu não quero perder você!)",
  ui_story_5061_50611201_86_dialog_content = "Admiro sua coragem. Vamos começar...",
  ui_story_5061_50611201_87_dialog_content = "Essas devem ser... as memórias de No. 33!",
  ui_story_5061_50611201_88_dialog_content = "Está funcionando, PlayerName?",
  ui_story_5061_50611201_89_dialog_content = "É verdade! As memórias dela estão em processo de recuperação!",
  ui_story_5061_50611201_90_dialog_content = "Sim, eu me lembro agora. Minha missão não é apenas proteger este lugar...",
  ui_story_5061_50611201_91_dialog_content = "E também, para proteger o mundo lá fora? Alina—",
  ui_story_5061_50611201_92_dialog_content = "Erro no Modelo Eco!",
  ui_story_5061_50611201_93_dialog_content = "Então, por que ela não está melhorando?",
  ui_story_5061_50611201_94_dialog_content = "Preciso usar meus poderes mais uma vez! Desta vez, tenho certeza de que posso alcançar o núcleo da consciência dela!",
  ui_story_5061_50611201_95_dialog_content = "Forçando o desligamento do módulo de memória...",
  ui_story_5061_50611201_96_dialog_content = "Não! Não! Eu não quero esquecê-la!",
  ui_story_5061_50611201_97_dialog_content = "<size=45>Me salve! ME SALVE! AHHHHH!</size>",
  ui_story_5061_50611202_1_dialog_content = "Ai...",
  ui_story_5061_50611202_2_dialog_content = "Ela parou!",
  ui_story_5061_50611202_3_dialog_content = "Você tem que ajudá-la, PlayerName!",
  ui_story_5061_50611202_4_option_content = "Aumento de Força",
  ui_story_5061_50611202_5_dialog_content = "<color=#e8d9bb>No insondável mar da consciência, uma figura frágil se encolhe.</color>",
  ui_story_5061_50611202_6_dialog_content = "A minha... minha missão, minha missão é...",
  ui_story_5061_50611202_7_dialog_content = "O concentrador de Lúmina foi descartado! Agora tudo que preciso fazer é desligá-lo e fechar este lugar.",
  ui_story_5061_50611202_8_dialog_content = "Eu sei que tem sido difícil para você todos esses anos, mas sua missão finalmente está completa.",
  ui_story_5061_50611202_9_dialog_content = "...!",
  ui_story_5061_50611202_10_dialog_content = "Desculpe por termos demorado tanto para te encontrar. Você deve ter se sentido tão solitário todo esse tempo.",
  ui_story_5061_50611202_11_dialog_content = "Por quê! Por que só está vindo até mim agora?",
  ui_story_5061_50611202_12_dialog_content = "A Lúmina esteve obstruída por tanto tempo, as relíquias foram danificadas por tanto tempo e eu estive errado por tanto tempo...",
  ui_story_5061_50611202_13_dialog_content = "Eu já decidi desistir...",
  ui_story_5061_50611202_14_dialog_content = "Mas você nunca desistiu, não é? E por isso, seremos sempre gratos.",
  ui_story_5061_50611202_15_dialog_content = "...",
  ui_story_5061_50611202_16_dialog_content = "Northland tem vivido em paz por tantos anos, tudo porque você nunca desistiu.",
  ui_story_5061_50611202_17_dialog_content = "Os lugares que não estavam sob a proteção dessas ruínas foram rapidamente dominados pelos Eclipsitas.",
  ui_story_5061_50611202_18_dialog_content = "Mas o povo de Northland tem vivido vidas felizes e pacíficas por muito tempo... E tudo graças a você.",
  ui_story_5061_50611202_19_dialog_content = "... Sério, por minha causa?",
  ui_story_5061_50611202_20_dialog_content = "Minha missão... tem significado?",
  ui_story_5061_50611202_21_dialog_content = "Claro que sim! Sua missão afetou todo o Northland e todos os aurorianos que vivem aqui!",
  ui_story_5061_50611202_22_dialog_content = "Chegar ao fim nunca foi o propósito da sua missão... O verdadeiro significado está em cada momento de paz que você trouxe para o povo deste reino.",
  ui_story_5061_50611202_23_dialog_content = "Então obrigado... Obrigado por tudo que você fez por nós.",
  ui_story_5061_50611202_24_dialog_content = "... Agradeço.",
  ui_story_5061_50611202_25_dialog_content = "... Eu lembro, uma vez... alguém também me encontrou assim...",
  ui_story_5061_50611202_26_dialog_content = "... Agradeceu-me pelo meu esforço e até se tornou meu companheiro.",
  ui_story_5061_50611202_27_dialog_content = "E há muitas outras pessoas que adorariam ser suas amigas também! Você não precisa mais carregar esse fardo sozinho!",
  ui_story_5061_50611202_28_dialog_content = "Todos aqui estão dispostos a lutar ao seu lado!",
  ui_story_5061_50611202_29_dialog_content = "... Mas eu... Após sair do combate, todos os dispositivos de conexão pararam de funcionar.",
  ui_story_5061_50611202_30_dialog_content = "... A partir de agora, sou apenas um pedaço de metal sem sentido.",
  ui_story_5061_50611202_31_dialog_content = "... Eu não sou útil para você.",
  ui_story_5061_50611202_32_dialog_content = "Isso não é verdade, de forma alguma. Seu coração, suas palavras, sua mente... Todas essas coisas nos dão força e ajudam a tornar o mundo um lugar melhor.",
  ui_story_5061_50611202_33_dialog_content = "Coração? Mente? Você quer dizer... você quer minha unidade de armazenamento? Interna ou externa?",
  ui_story_5061_50611202_34_dialog_content = "Eu, ah... Acho que não faz diferença, na verdade! Ei, você poderia me dizer uma coisa? Northland era um lugar quente no passado?",
  ui_story_5061_50611202_35_dialog_content = "Estava quente.",
  ui_story_5061_50611202_36_dialog_content = "Por que, mesmo?",
  ui_story_5061_50611202_37_dialog_content = "Devido às diferentes posições do círculo crepuscular, no passado deste mundo, não existiam coisas como dias eternos e noites eternas.",
  ui_story_5061_50611202_38_dialog_content = "Entendi, então Antony estava certo o tempo todo! Muito obrigado, No. 33! Você acabou de dar ao mundo uma resposta muito importante sobre o seu passado!",
  ui_story_5061_50611202_39_dialog_content = "No entanto, não sei por que é assim e não posso fornecer as respostas reais.",
  ui_story_5061_50611202_40_dialog_content = "Tudo bem também! Descobrir a verdade é o objetivo da nossa jornada. É algo que todo auroriano vivo sabe, de alguma forma ou de outra.",
  ui_story_5061_50611202_41_dialog_content = "Entendi.",
  ui_story_5061_50611202_42_dialog_content = "Diga... Você quer vir junto conosco?",
  ui_story_5061_50611202_43_dialog_content = "Eu?",
  ui_story_5061_50611202_44_dialog_content = "Claro! Afinal, você também faz parte do nosso mundo. Não quer experimentar por si mesmo?",
  ui_story_5061_50611202_45_dialog_content = "Vamos lá! O primeiro passo é sempre o mais difícil, mas você vai ficar bem!",
  ui_story_5061_50611202_46_dialog_content = "... Mas... meus dispositivos de conexão... já perdi a capacidade de receber sinais externos. Eu...",
  ui_story_5061_50611202_47_dialog_content = "Apenas siga um passo de cada vez e prometo que você não vai cair.",
  ui_story_5061_50611202_48_dialog_content = "Eles não me chamam de Navegador à toa, sabe! Eu serei seus olhos, então apenas mantenha a cabeça erguida!",
  ui_story_5061_50611202_49_dialog_content = "Isso é...",
  ui_story_5061_50611202_50_dialog_content = "Um transmissor improvisado e bagunçado... configurado para combinar especificamente com o meu canal...",
  ui_story_5061_50611202_51_dialog_content = "Pronto? Três, dois, um...",
  ui_story_5061_50611202_52_dialog_content = "Bem-vindo ao mundo lá fora!",
  ui_story_5061_50611202_53_dialog_content = "Desculpe, não tivemos a chance de nos apresentarmos adequadamente antes.",
  ui_story_5061_50611202_54_dialog_content = "Este é o Mestre Novio, um espírito das montanhas de Northland. Seu escudo protegeu nossa Lumina de ser absorvida agora há pouco.",
  ui_story_5061_50611202_55_dialog_content = "Foi assim que PlayerName conseguiu usar seus poderes em No. 33 sem ser contra-atacado.",
  ui_story_5061_50611202_56_dialog_content = "Prazer em conhecê-la, Srta. Zarya.",
  ui_story_5061_50611202_57_dialog_content = "Pelo bem de Northland e pelo futuro de todos os Aurorianos, peço que mantenhamos este incidente em segredo.",
  ui_story_5061_50611202_58_dialog_content = "Embora os eventos de hoje tenham sido incrivelmente significativos, não podemos permitir que as outras forças tomem conhecimento do que aconteceu aqui. Dado o estado atual das coisas, não temos escolha a não ser permitir um certo grau de investigação externa neste lugar.",
  ui_story_5061_50611202_59_dialog_content = "No entanto, eu humildemente imploro que você mantenha a conexão entre essas ruínas e a Centelha como um segredo bem guardado.",
  ui_story_5061_50611202_60_dialog_content = "Embora a praga dos Eclipsitas seja um problema constante para Sua Majestade... Está longe de ser sua maior preocupação.",
  ui_story_5061_50611202_61_dialog_content = "Aurorianos e sua busca destrutiva por um poder cada vez maior... Isso é o que mais preocupa Queen Bethlehem.",
  ui_story_5061_50611202_62_dialog_content = "... Entendido. O mundo ainda não está pronto para uma descoberta como essa.",
  ui_story_5061_50611202_63_dialog_content = "... Muito bem, Mestre Novio.",
  ui_story_5061_50611202_64_dialog_content = "Obrigado a todos pela cooperação. Se me derem licença, preciso ir agora...",
  ui_story_5061_50611202_65_dialog_content = "<size=45>Espere!</size>",
  ui_story_5061_50611202_66_dialog_content = "Hum? Há... algum problema, Srta. Zarya?",
  ui_story_5061_50611202_67_dialog_content = "D-Desculpe, eu não quis gritar assim...",
  ui_story_5061_50611202_68_dialog_content = "Eu... Eu só queria saber... O que aconteceu com minha irmã no final...",
  ui_story_5061_50611202_69_dialog_content = "O nome dela era Alina. Há cem anos, ela...",
  ui_story_5061_50611202_70_dialog_content = "... era o capitão dos Patrulheiros da Primavera, que estavam presentes durante o incidente da Aurorastorm. Está correto?",
  ui_story_5061_50611202_71_dialog_content = "V-Você ainda se lembra?!",
  ui_story_5061_50611202_72_dialog_content = "Seu conhecimento parece estar um pouco desatualizado, Srta. Zarya.",
  ui_story_5061_50611202_73_dialog_content = "Hã?",
  ui_story_5061_50611202_74_dialog_content = "Agora, por favor, deixe-me... Não, por favor, permita-me transmitir o \"final\" da Srta. Alina para você.",
  ui_story_5061_50611202_75_dialog_content = "... Você!",
  ui_story_5061_50611202_76_dialog_content = "Não precisa se preocupar. PlayerName já me ajudou a reiniciar meu Modelo de Eco para recuperar minhas memórias. Mas ele ainda não despertou do enorme esgotamento.",
  ui_story_5061_50611202_77_dialog_content = "O eu atual não vai mais se envolver em ações incontroláveis.",
  ui_story_5061_50611202_78_dialog_content = "... T-Tudo bem, por favor me diga o que aconteceu com minha irmã.",
  ui_story_5061_50611202_79_dialog_content = "Naquele dia, justo quando a Srta. Alina decidiu se sacrificar...",
  ui_story_5061_50611202_80_dialog_content = "Alina! Você está aí?!",
  ui_story_5061_50611202_81_dialog_content = "Isso parece com Zarya! Mas como ela me encontrou aqui?!",
  ui_story_5061_50611202_82_dialog_content = "Há um desvio na calibração automática do concentrador!",
  ui_story_5061_50611202_83_dialog_content = "É atraído por um navio reserva mais poderoso!",
  ui_story_5061_50611202_84_dialog_content = "(Se eu escolher um indivíduo com maior talento e taxas de sobrevivência para completar o protocolo... todos eles poderão sobreviver!)",
  ui_story_5061_50611202_85_dialog_content = "Cálculo concluído! Execute o plano otimizado!",
  ui_story_5061_50611202_86_dialog_content = "O que eu faço agora?!",
  ui_story_5061_50611202_87_dialog_content = "Corra! Quanto mais longe, melhor! Este lugar está prestes a ser completamente destruído!",
  ui_story_5061_50611202_88_dialog_content = "Mas o que vai acontecer com você e Zarya?!",
  ui_story_5061_50611202_89_dialog_content = "—A Srta. Zarya quer que você sobreviva, e eu também.",
  ui_story_5061_50611202_90_dialog_content = "Então, de uma só vez, você liberou todo o seu poder, aniquilando todos os Eclipsitas presentes.",
  ui_story_5061_50611202_91_dialog_content = "Como um efeito colateral da energia, ela selou você e todas as ruínas no gelo.",
  ui_story_5061_50611202_92_dialog_content = "A razão pela qual você conseguiu acessar minhas memórias através da Lumina das ruínas agora é porque as ruínas já o reconheceram como parte dela.",
  ui_story_5061_50611202_93_dialog_content = "Isso significa que minha irmã... Conseguiu escapar?",
  ui_story_5061_50611202_94_dialog_content = "Sim. Logo depois, Lady Alina retornou em segurança para Northland junto com seus companheiros feridos.",
  ui_story_5061_50611202_95_dialog_content = "Foi então que ela relatou a existência de No. 33... Ou melhor, o Espírito da Aurora.",
  ui_story_5061_50611202_96_dialog_content = "... Então ela sobreviveu, afinal! Minha irmã conseguiu sair viva!",
  ui_story_5061_50611202_97_dialog_content = "Espere... Se eu me tornei o novo recipiente e Alina sobreviveu por causa disso...",
  ui_story_5061_50611202_98_dialog_content = "Isso significa... que eu a protegi?",
  ui_story_5061_50611202_99_dialog_content = "Parece que sim. Lady Alina ficou devastada com a perda de sua irmã mais nova e, assim como você, veio a este mesmo lugar para procurar por você.",
  ui_story_5061_50611202_100_dialog_content = "Infelizmente, o gelo cobrindo a montanha estava ainda mais denso naquela época, e o estado adormecido de No. 33 a impedia de enviar ou receber sinais. Como resultado, nossos esforços de busca foram em vão.",
  ui_story_5061_50611202_101_dialog_content = "Alina... Sinto muito mesmo. Não consigo imaginar o quanto você deve ter sofrido...",
  ui_story_5061_50611202_102_dialog_content = "No entanto, a Senhora Alina logo encontrou forças para retomar seus deveres.",
  ui_story_5061_50611202_103_dialog_content = "!",
  ui_story_5061_50611202_104_dialog_content = "Quando eu disse que seu conhecimento estava um pouco desatualizado, não foi apenas porque sua irmã conseguiu sobreviver...",
  ui_story_5061_50611202_105_dialog_content = "Mas isso ocorreu porque a Senhora Alina se tornou uma <color=#FFB400>Guardiã do Tribunal de Northland</color>. Ela serviu fiel e admiravelmente por muitos anos e faleceu pacificamente aos veneráveis 83 anos de idade.",
  ui_story_5061_50611202_106_dialog_content = "Um guardião do tribunal real... Esse era o sonho dela!",
  ui_story_5061_50611202_107_dialog_content = "*Soluçando* Eu... eu estou tão feliz... Minha irmã conseguiu realizar seu sonho!",
  ui_story_5061_50611202_108_dialog_content = "No dia de sua promoção, a Senhora Alina teve estas palavras a dizer:",
  ui_story_5061_50611202_109_dialog_content = "Ufa! Parece que finalmente estou tão forte quanto o Zarya sempre achou que eu era!",
  ui_story_5061_50611202_110_dialog_content = "Não se preocupe, Alina... Vou garantir que eu viva bem por nós duas!",
  ui_story_5061_50611202_111_dialog_content = "Eu te protegi... Isso também me torna forte? Snif...",
  ui_story_5061_50611202_112_dialog_content = "E... eu prometo viver bem por nós dois também...",
  ui_story_5061_50611202_113_dialog_content = "Obrigado, Alina... Minha doce, doce irmã...",
  ui_story_5061_50611202_114_dialog_content = "<size=45>...Uaaaaaaah!!!</size>",
  ui_story_5061_50611202_115_dialog_content = "(Ugh... Minha cabeça está girando...)",
  ui_story_5061_50611202_116_dialog_content = "(Alguém... está chorando?)",
  ui_story_5061_50611202_117_dialog_content = "Zarya... você estava chorando agora há pouco?",
  ui_story_5061_50611202_118_dialog_content = "...!",
  ui_story_5061_50611202_119_dialog_content = "O-Claro que não!",
  ui_story_5061_50611202_120_dialog_content = "Mas seus olhos estão todos vermelhos e inchados...",
  ui_story_5061_50611202_121_dialog_content = "É só neve! Eu peguei neve nos meus olhos!",
  ui_story_5061_50611202_122_dialog_content = "Pfffff—",
  ui_story_5061_50611202_123_dialog_content = "E de que exatamente você está rindo, Sr. Antony?!",
  ui_story_5061_50611202_124_dialog_content = "Ah, nada! De qualquer forma, Mestre Novio, muito obrigado por—",
  ui_story_5061_50611202_125_dialog_content = "Hã? Para onde ele foi?",
  ui_story_5061_50611202_126_dialog_content = "Ele estava aqui há um segundo atrás...",
  ui_story_5061_50611301_1_dialog_content = "<color=#e8d9bb>Algum tempo depois...</color>",
  ui_story_5061_50611301_2_dialog_content = "Tudo bem, essa deve ser a última leva de peças.",
  ui_story_5061_50611301_3_dialog_content = "Reunir todos esses componentes foi um grande desafio. Vasculhamos cada centímetro da montanha só para colocar as mãos neles!",
  ui_story_5061_50611301_4_dialog_content = "Felizmente, o Mestre Novio tem monitorado de perto as ruínas espalhadas pela paisagem do nosso reino. Caso contrário, nunca teríamos coletado tantas peças utilizáveis.",
  ui_story_5061_50611301_5_dialog_content = "Apesar dos nossos melhores esforços, ainda não conseguimos consertar esta instalação. Sinto muito.",
  ui_story_5061_50611301_6_dialog_content = "Por que você está pedindo desculpas, No. 33? Não estamos tentando consertar as ruínas, lembra? Só queremos desligar o concentrador de Lúmina.",
  ui_story_5061_50611301_7_dialog_content = "Após uma avaliação minuciosa dos danos no concentrador, o Palácio Invernal considerou-o muito perigoso para continuar sendo usado. A decisão mais sensata no momento é desligá-lo.",
  ui_story_5061_50611301_8_dialog_content = "Mestre Novio está ajustando o fornecimento de energia das ruínas próximas para compensar a falta de cobertura da barreira. A Lúmina dessas ruínas também será redirecionada.",
  ui_story_5061_50611301_9_dialog_content = "Pelo menos, foi mais ou menos assim que entendi o plano dele. O resto, no entanto, está além da minha compreensão...",
  ui_story_5061_50611301_10_dialog_content = "De qualquer forma, a anomalia do Lumina deve ser resolvida em breve.",
  ui_story_5061_50611301_11_dialog_content = "Uma vez que o concentrador seja desativado, o Tribunal pode providenciar os reparos em uma data posterior.",
  ui_story_5061_50611301_12_dialog_content = "Então você acha que conseguiremos desativar o concentrador usando essas peças?",
  ui_story_5061_50611301_13_dialog_content = "Sim, um desligamento direto pode provocar um colapso ou explosão. Teremos que esperar até que o módulo central seja reparado antes de desligá-lo.",
  ui_story_5061_50611301_14_dialog_content = "Durante o desligamento, o Lumina acumulado a longo prazo dentro do concentrador será eliminado.",
  ui_story_5061_50611301_15_dialog_content = "Isso pode levar a terremotos menores e fenômenos de aurora. Por favor, prepare-se para o possível impacto.",
  ui_story_5061_50611301_16_dialog_content = "Muito bem, vou iniciar o processo de desligamento agora.",
  ui_story_5061_50611301_17_dialog_content = "Uma vez desativado, você não precisará mais ficar conectado a ele, certo?",
  ui_story_5061_50611301_18_dialog_content = "Sim. Não vou precisar de conexão, pelo menos até começar os trabalhos de reparo.",
  ui_story_5061_50611301_19_dialog_content = "Então... Quer dar uma olhada no meu Colosso?",
  ui_story_5061_50611301_20_dialog_content = "Você disse que queria ver como outros Aurorianos vivem no mundo, não foi?",
  ui_story_5061_50611301_21_dialog_content = "?",
  ui_story_5061_50611301_22_dialog_content = "Eu...",
  ui_story_5061_50611301_23_dialog_content = "Eu vivenciei uma emoção que raramente foi registrada antes. Será que isso é... hesitação?",
  ui_story_5061_50611301_24_dialog_content = "Talvez a empolgação esteja subindo à sua cabeça? Hmm, eu me pergunto como você descreveria isso...",
  ui_story_5061_50611301_25_dialog_content = "Entendi! Seu dispositivo de armazenamento está temporariamente sobrecarregado!",
  ui_story_5061_50611301_26_dialog_content = "Olha, está começando!",
  ui_story_5061_50611301_27_dialog_content = "<color=#e8d9bb>Rumble—Rumble—Rumble—</color>",
  ui_story_5061_50611301_28_dialog_content = "<color=#e8d9bb>O Lumina, há muito obstruído, finalmente é liberado agora, retornando ao ciclo de energia de Astra.</color>",
  ui_story_5061_50611301_29_dialog_content = "<color=#e8d9bb>Uma vez mais, a deslumbrante aurora surge nos céus na fronteira.</color>",
  ui_story_5061_50611301_30_dialog_content = "Você realmente precisa ver para acreditar...",
  ui_story_5061_50611301_31_dialog_content = "Esta aurora parece ter saído de um conto de fadas. Eu não fazia ideia de que algo assim pudesse ser criado por uma máquina.",
  ui_story_5061_50611301_32_dialog_content = "No continente de Astra, existem muitas instalações de energia como esta.",
  ui_story_5061_50611301_33_dialog_content = "O poder deles se conecta diretamente ao núcleo da Terra, simbolizando a incrível força das civilizações antigas em remodelar o mundo.",
  ui_story_5061_50611301_34_dialog_content = "Mas uma aurora como essa só pode ser vista aqui, certo?",
  ui_story_5061_50611301_35_dialog_content = "Isso mesmo. Só é visível aqui por causa da nossa posição perto do círculo crepuscular, onde a luz e a escuridão se encontram.",
  ui_story_5061_50611301_36_dialog_content = "Os céus são extremamente claros nesta área e a colisão das partículas de Lumina é muito perceptível aqui!",
  ui_story_5061_50611301_37_dialog_content = "Sonhei com esse momento mais vezes do que posso contar... Mas nada se compara a vê-lo com meus próprios olhos.",
  ui_story_5061_50611301_38_dialog_content = "Antony...",
  ui_story_5061_50611301_39_dialog_content = "(Deve haver tantas outras pessoas como ele no mundo: pessoas que exploram o desconhecido com apenas sua intuição e conhecimento autodidata para guiá-los...)",
  ui_story_5061_50611301_40_dialog_content = "(Fico feliz em saber que pessoas como ele podem descobrir os segredos do mundo e realizar seus sonhos também.)",
  ui_story_5061_50611301_41_dialog_content = "Finalmente entendo por que você está constantemente buscando respostas para as perguntas mais difíceis da vida, Antony.",
  ui_story_5061_50611301_42_dialog_content = "A maneira como meu coração está acelerado agora...",
  ui_story_5061_50611301_43_dialog_content = "Isso me faz querer explorar questões ainda mais profundas sobre o nosso mundo.",
  ui_story_5061_50611301_44_dialog_content = "... Por exemplo: Em que tipo de mundo realmente vivemos?",
  ui_story_5061_50611301_45_dialog_content = "... De onde nós viemos?",
  ui_story_5061_50611301_46_dialog_content = "... Para onde eles estão indo?"
}
return config
